/**  One action's result, for a request that answers with several. */
export type ActionReply = 
/**  The device answered. */
{ status: "ok"; 
/**  What came of the action. */
data: ActionOutcome } | 
/**  The action never reached the device, or no result came. */
{ status: "error"; 
/**  Why. */
error: CommandError };

/**  What an agent is doing. Decision N-1 lists the states and how each looks. */
export type Activity = 
/**  Launching, or resuming after a restart. */
{ state: "starting" } | 
/**  Working. */
{ state: "busy" } | 
/**  Waiting on its own sub-agents, which are still working. */
{ state: "busy_in_subagents" } | 
/**  Blocked on a permission prompt or a question. */
{ state: "needs_input"; 
/**  The prompt to answer. */
attention: AttentionId } | 
/**  Finished a turn you haven't looked at yet. */
{ state: "done_unread" } | 
/**
 *  Waiting for a prompt, and the vendor still has the conversation cached,
 *  so the next turn is cheaper and faster.
 */
{ state: "idle_cache_warm"; 
/**  When the cache is expected to expire. */
warm_until: Timestamp } | 
/**  Waiting for a prompt. */
{ state: "idle" } | 
/**  Hit a usage limit, and continues when it resets. */
{ state: "waiting_for_limit_reset"; 
/**  When the limit resets, if the vendor said. */
resets_at: Timestamp | null } | 
/**  Not running until you press Resume. */
{ state: "paused"; 
/**  Why it paused. */
reason: PauseReason } | 
/**  The CLI exited or crashed. */
{ state: "error"; 
/**  The exit status or crash message. */
reason: string } | 
/**  The app can't reach the agent's device or workspace. */
{ state: "not_accessible" };

/**
 *  Who calls the agent tools: an agent MaxHQ holds, a tool outside it
 *  with an access key, or a scheduled task.
 */
export type Actor = 
/**  An agent. */
{ kind: "agent"; 
/**  The agent. */
agent: AgentId } | 
/**  A tool with an access key. */
{ kind: "key"; 
/**  The key. */
key: KeyId } | 
/**  A scheduled task, on each run. */
{ kind: "task"; 
/**  The task. */
task: TaskId };

/**
 *  A card that asks whether to let in a program that connected without a
 *  key the device trusts, and asked for more than such a connection may
 *  do. A proven desktop app answers it with
 *  [`crate::ClientMessage::AnswerAdmission`]. A yes lasts until the program
 *  disconnects.
 */
export type Admission = {
	/**  The card. */
	id: AdmissionId,
	/**  The device the program connected to. */
	device: DeviceId,
	/**
	 *  What the card asks, with its consent laid out. The consent's facts
	 *  describe the connection: what it says it is, how it reached `maxd`,
	 *  and on a Mac the program behind it.
	 */
	question: Question,
	/**  When the device raised the card. */
	raised_at: Timestamp,
	/**  When an unanswered card counts as Don't allow. */
	expires_at: Timestamp,
};

/**
 *  A card that asks whether to let in a program that proved no app key
 *  the device trusts.
 */
export type AdmissionId = string;

/**  An agent CLI session, or a sub-agent inside one. */
export type Agent = {
	/**  Stable across restarts and resumes. */
	id: AgentId,
	/**  The workspace the agent runs in. */
	workspace: WorkspaceId,
	/**
	 *  The git branch the agent works on, when `maxd` knows it. In a
	 *  container each agent has a worktree on its own branch.
	 */
	branch: string | null,
	/**  Set for a sub-agent, and names the agent that started it. */
	parent: AgentId | null,
	/**  Which CLI this is. */
	vendor: Vendor,
	/**  The login it runs under. Sub-agents use their parent's. */
	account: AccountId | null,
	/**  The model it runs, as the CLI names it. Unset for observed agents. */
	model: string | null,
	/**  The permission mode it runs in. Unset for observed agents. */
	permission: AgentPermission | null,
	/**  The terminal session holding the CLI. Sub-agents have none. */
	session: SessionId | null,
	/**
	 *  The CLI's own session ID, which a resume passes back to it. Claude
	 *  calls it the session ID and Codex the thread ID.
	 */
	vendor_session_id: string | null,
	/**  Who holds the CLI's terminal. */
	control: Control,
	/**
	 *  The CLI's process ID on its device, or inside its container. Unset
	 *  for sub-agents and once the process is gone.
	 */
	pid: number | null,
	/**
	 *  Whether `maxd` can reach the agent itself. Decision N-2 shows a
	 *  device that answers with an agent that doesn't as purple.
	 */
	link: AgentLink,
	/**  A short name, from the CLI or from the first prompt. */
	title: string,
	/**  What the agent is doing. */
	activity: Activity,
	/**  How full its context window is, when the CLI reports it. */
	context: ContextUsage | null,
	/**  When the agent first started. */
	started_at: Timestamp,
	/**  When the agent last produced output or changed activity. */
	last_activity_at: Timestamp,
	/**
	 *  Where the agent sits in the sidebar: settled, snoozed or pinned. A
	 *  `maxd` from before inboxes leaves this out, and reads as active.
	 */
	inbox?: Inbox,
	/**  Who started it through the agent tools, if anyone did. */
	origin?: AgentOrigin | null,
	/**
	 *  The PRs linked to its work. A `maxd` from before PRs leaves this
	 *  out.
	 */
	pulls?: PullLink[],
	/**
	 *  Set while `maxd` waits for an agent's turn in your own terminal to
	 *  end, to stop the CLI there and continue the session here. A `maxd`
	 *  from before leaves this out.
	 */
	taking_over?: boolean,
	/**
	 *  Set while `maxd` has stopped the CLI because it sat idle. The next
	 *  message starts it again, and that clears it. A `maxd` from before
	 *  leaves this out.
	 */
	asleep?: boolean,
	/**
	 *  The effort level its next turn runs at, as the CLI names it. None
	 *  when it runs at its model's [`ModelChoice::default_effort`], as an
	 *  agent started before `maxd` named a level does. A `maxd` from
	 *  before [`crate::message::EFFORT_SINCE`] leaves this out.
	 */
	effort?: string | null,
	/**
	 *  What the agent started that still runs, and what it waits on. Unset
	 *  when there's neither, for sub-agents, and from a `maxd` from before
	 *  [`crate::message::PROCESSES_SINCE`].
	 */
	running?: AgentRunning | null,
	/**  Where the agent moved between devices, if it did. */
	moved?: Moved | null,
};

/**  An agent on a device, such as the one a moved agent became. */
export type AgentAt = {
	/**  The device. */
	device: DeviceId,
	/**  The agent. */
	agent: AgentId,
};

/**  What a new permission starts with. */
export type AgentDefaults = {
	/**  The limits, all off until you set them. */
	limits: Limits,
	/**  How many levels of agents it reaches. */
	depth: number,
};

/**
 *  An agent's timeline as Markdown, cut to a budget, for an agent pill
 *  that travels as a file.
 */
export type AgentExcerpt = {
	/**  A file name for it, such as `agent-api-refactor.md`. */
	name: string,
	/**  The Markdown. */
	text: string,
	/**  How many messages it holds. */
	messages: number,
	/**  How many messages it left out to fit the budget. */
	omitted: number,
};

/**  An agent CLI session, or a sub-agent inside one. */
export type AgentId = string;

/**  Whether `maxd` can reach an agent. */
export type AgentLink = 
/**  The agent's process runs and `maxd` can see it. */
{ state: "live" } | 
/**  The device answers but the agent doesn't run. */
{ state: "down"; 
/**
 *  Why, such as "exited", "container stopped" or "interrupted by a
 *  restart".
 */
reason: string; 
/**  When `maxd` noticed, if it knows. */
since: Timestamp | null } | 
/**  `maxd` can't tell yet, such as just after it started. */
{ state: "unknown" };

/**
 *  One step of moving an agent to another device. Only the device that
 *  runs the MaxHQ app asks for these, of the device the agent leaves and
 *  the one it goes to.
 */
export type AgentMoveStep = 
/**
 *  Lists the vendors, accounts, models and folders an agent could run
 *  with on the asked device. The outcome is
 *  [`crate::message::ActionOutcome::Tool`], as `list_targets` answers.
 */
{ step: "targets" } | 
/**
 *  Checks that the account is signed in and the folder is there. The
 *  outcome is [`crate::message::ActionOutcome::Checked`], naming what
 *  the agent will run as.
 */
{ step: "check"; 
/**  Where the agent goes. */
to: MoveTo } | 
/**
 *  Says whether the agent could leave now and what it would take
 *  along, without stopping it or summing anything up. The outcome is
 *  [`crate::message::ActionOutcome::Departed`] with no brief.
 */
{ step: "look"; 
/**  The agent. */
agent: AgentId } | 
/**
 *  Stops the agent, or refuses while it works unless `stop` is set,
 *  and sums up its conversation. The outcome is
 *  [`crate::message::ActionOutcome::Departed`].
 */
{ step: "leave"; 
/**  The agent. */
agent: AgentId; 
/**  Whether to stop a turn that runs or a prompt that waits. */
stop?: boolean } | 
/**
 *  Starts the agent from what it took along. The outcome is
 *  [`crate::message::ActionOutcome::Started`].
 */
{ step: "arrive"; 
/**  The start. */
arrival: Arrival } | 
/**
 *  Marks the agent moved and settles it, and takes back the
 *  permissions of the tasks that left with it. The outcome is
 *  [`crate::message::ActionOutcome::Done`].
 */
{ step: "settle"; 
/**  The agent that left. */
agent: AgentId; 
/**  The agent it became. */
to: AgentAt; 
/**  The task permissions to take back. */
revoke?: PermissionId[] };

/**
 *  Who started an agent, kept with it so it nests under its caller and a
 *  stop reaches it.
 */
export type AgentOrigin = {
	/**  The permission it was started under. */
	permission: PermissionId,
	/**  The agent or key that started it. */
	by: Actor,
	/**  The device the caller is on. */
	device: DeviceId,
	/**
	 *  How many levels below the permission's holder the agent is: 1 for
	 *  one the holder started.
	 */
	level?: number,
	/**
	 *  Whether the caller gets a message each time the agent finishes a
	 *  turn.
	 */
	wake?: boolean,
	/**
	 *  The container workspace the caller ran in on `device`, if it ran in
	 *  one. A task an agent in a container made keeps it, so its runs stay
	 *  there as the agent would.
	 */
	container?: WorkspaceId | null,
};

/**  The mode you asked for, and the one the CLI reports running. */
export type AgentPermission = {
	/**  The mode you asked for. */
	requested: PermissionMode,
	/**
	 *  The mode the CLI reports running, once it has. It differs from
	 *  `requested` when the CLI refused or changed it.
	 */
	effective: PermissionMode | null,
};

/**  Where a new agent runs. */
export type AgentPlace = 
/**  In a workspace `maxd` already knows. */
{ type: "workspace"; 
/**  The workspace to run in. */
workspace: WorkspaceId } | 
/**  In any folder on the device. */
{ type: "folder"; 
/**  Absolute path on the device. */
path: string };

/**  One process in an agent's tree. The holder itself isn't one. */
export type AgentProcess = {
	/**  Its process ID, as its device or container sees it. */
	pid: number,
	/**  Its parent's process ID. The CLI's is the holder's. */
	parent: number,
	/**
	 *  When it started, in its device's own units. Only its device reads
	 *  it: with `pid` it names this process to
	 *  [`crate::ClientMessage::SignalProcess`], so a reused pid is never
	 *  signalled.
	 */
	start: number,
	/**  How long it has run, in milliseconds. */
	run_ms: number,
	/**  The CPU time it has used, user and system, in milliseconds. */
	cpu_ms: number,
	/**  Its resident memory, in bytes. */
	memory: number,
	/**  Its process name. */
	name: string,
	/**  Its command line, cut to 1,024 bytes. */
	command: string,
	/**
	 *  Whether it's the agent's own CLI, which only stopping the agent
	 *  stops.
	 */
	cli: boolean,
	/**
	 *  The ports it listens on, as port detection counts them, lowest
	 *  first.
	 */
	ports: number[],
};

/**
 *  What a lead agent started that still runs, and what it waits on, sent
 *  on [`crate::model::Agent::running`] so a list shows it without asking.
 *  Its `maxd` sends it again only when it changes.
 */
export type AgentRunning = {
	/**
	 *  How many jobs the agent started still run: its background shells
	 *  and what its commands left behind, not its CLI or the CLI's own
	 *  servers.
	 */
	count: number,
	/**  A short name for each of the oldest few, such as `pnpm dev`. */
	names: string[],
	/**
	 *  Set while the agent waits on something that wakes it, so it acts
	 *  again by itself.
	 */
	waiting?: AgentWait | null,
};

/**  What a new agent should be. */
export type AgentSpec = {
	/**  Which CLI to run. */
	vendor: Vendor,
	/**  The login to run it under. */
	account: AccountId,
	/**  Where to run it. */
	place: AgentPlace,
	/**  The model to run, or none for the account's default. */
	model: string | null,
	/**  Unset means the device's default. */
	permission: PermissionMode | null,
	/**  A name to show, or none to take one from the CLI or the first message. */
	title: string | null,
	/**  The first message, sent once the agent is up. */
	first: UserInput | null,
	/**
	 *  The git branch for the agent's worktree in a container. `maxd`
	 *  names one when it's unset.
	 */
	branch: string | null,
	/**
	 *  Who started it through the agent tools, set by `maxd`. A client
	 *  leaves it out.
	 */
	origin?: AgentOrigin | null,
	/**
	 *  The effort level it starts at, or none for the device's default for
	 *  its vendor. Only Claude Code and Codex take one. A `maxd` from
	 *  before [`EFFORT_SINCE`] ignores it.
	 */
	effort?: string | null,
};

/**  What an idle agent waits on, which wakes it by itself. */
export type AgentWait = 
/**
 *  A background command or monitor the CLI watches. The agent goes on
 *  when it ends.
 */
{ kind: "task"; 
/**  What it runs, in a few words. */
name: string } | 
/**  A wakeup the agent set for itself. */
{ kind: "wakeup"; 
/**  When it's due. */
at: Timestamp };

/**  The workflow variables you allowed for a project's agents on a device. */
export type AllowedWorkflowEnv = {
	/**  Each variable, by name. A change to any asks again. */
	vars: AllowedWorkflowVar[],
	/**  When you allowed them. */
	at: Timestamp,
};

/**  One workflow variable you allowed. */
export type AllowedWorkflowVar = {
	/**  Its name. */
	name: string,
	/**
	 *  The SHA-256 of its value, in hex, so the value itself stays in the
	 *  workflow's files.
	 */
	digest: string,
};

/**  What happened to an answer. */
export type AnswerOutcome = 
/**  Yours was first, and the agent has it. */
{ status: "accepted" } | 
/**  Someone answered first. */
{ status: "already_answered"; 
/**  When the first answer arrived. */
answered_at: Timestamp; 
/**  The client that sent it. */
answered_by: ClientId } | 
/**  The event expired before the answer arrived. */
{ status: "expired" } | 
/**  `maxd` has no event with that ID. */
{ status: "unknown_event" } | 
/**
 *  An outcome from a newer `maxd`. The answer arrived, and what it came
 *  to needs a newer app to show.
 */
{ status: "unknown" };

/**
 *  What the footer shows, and what a bug report needs to say which build it
 *  came from.
 */
export type AppInfo = {
	/**  The app's version, from the workspace manifest. */
	version: string,
	/**  The protocol version this build speaks to `maxd`. */
	protocol_version: number,
	/**  The `maxd` builds this app carries for other devices. */
	bundled: BundledBuild[],
};

/**
 *  An app key a device trusts. A connection that proves it holds one may
 *  do everything the app does.
 */
export type AppKey = {
	/**  From [`AppKey::id_for`]. */
	id: AppKeyId,
	/**  The device that trusts it. */
	device: DeviceId,
	/**  The Ed25519 public key, as base64url of its 32 bytes, unpadded. */
	public_key: string,
	/**  What the key is called, such as "MaxHQ on studio-mac". */
	label: string,
	/**  When the device started trusting it. */
	added_at: Timestamp,
	/**
	 *  How the device came to trust it. One from a newer `maxd` reads as
	 *  unknown, so the key still shows.
	 */
	origin: AppKeyOrigin,
	/**
	 *  When a connection last proved it holds the key, or none since the
	 *  device started trusting it.
	 */
	proved_at: Timestamp | null,
};

/**  An app key one device trusts, derived from the device and the key. */
export type AppKeyId = string;

/**  How a device came to trust an app key. */
export type AppKeyOrigin = 
/**  The Mac checked the code signature of the app that offered it. */
"signature" | 
/**  Setup sent it along with MaxHQ's SSH key. */
"setup" | 
/**  It was the first key offered while the device trusted none. */
"first" | 
/**  You allowed it from a card on another device. */
"approved" | 
/**
 *  An app the device already trusted added it, such as when it changed
 *  its key.
 */
"app" | 
/**  A way from a newer `maxd`. */
"unknown";

/**  This Mac's app key, as Settings shows it. */
export type AppKeyState = {
	/**  The key, as base64url of its 32 bytes, unpadded. */
	public_key: string,
	/**  The key before it, while devices move off it. */
	previous: string | null,
	/**  The devices still on the key before, while one waits. */
	waiting: DeviceId[],
	/**  The devices that turned the key down since the app opened. */
	refusals: KeyRefusal[],
	/**  Why the app made a new key as it opened, when it had to. */
	remade: string | null,
	/**
	 *  Whether the Keychain holds the key. When it doesn't, the key lasts
	 *  until you quit.
	 */
	kept: boolean,
};

/**  What the settings page shows about the app's own update. */
export type AppUpdate = {
	/**  This app's version. */
	version: string,
	/**  Where its update stands. */
	status: UpdateStatus,
	/**  Your settings for it. */
	prefs: UpdatePrefs,
	/**
	 *  The page that lists the releases, taken from where the updater
	 *  looks, when that is a GitHub release download. A release's notes are
	 *  at `<release_notes>/tag/v<version>`.
	 */
	release_notes: string | null,
};

/**
 *  Sent whenever the update's status changes, so the prompt and the
 *  settings page follow it.
 */
export type AppUpdateChanged = UpdateStatus;

/**  What an agent asks approval for. */
export type ApprovalKind = 
/**  To run a shell command. */
"command" | 
/**  To edit files. */
"file_change" | 
/**  To read a file. */
"file_read" | 
/**  To reach the network. */
"network" | 
/**  To use a tool. */
"tool" | 
/**  To start on a plan. */
"plan" | 
/**  Anything else. */
"other";

/**  What starts a moved agent on the device it goes to. */
export type Arrival = {
	/**  Where it goes. */
	to: MoveTo,
	/**  The agent it was. */
	from: AgentAt,
	/**  What it took along. */
	departure: Departure,
	/**
	 *  The permissions of the tasks that follow it, which the asking device
	 *  keeps.
	 */
	grants?: Permission[],
};

/**  A file or folder staged to send to an agent. */
export type AttachmentId = string;

/**  How a CLI takes an attachment. */
export type AttachmentKind = 
/**  A picture the model can see. */
"image" | 
/**  A PDF the model can read. */
"pdf" | 
/**  Any other file, passed by path. */
"file" | 
/**  A folder, passed by path. */
"folder";

/**  The interface labels on the attachment picker. */
export type AttachmentPickerLabels = {
	prompt: string,
	message: string,
};

/**  A file or folder on the device, ready to send. */
export type AttachmentRef = {
	/**  Names the attachment in [`crate::message::UserInput::attachments`]. */
	id: AttachmentId,
	/**  The file name to show. */
	name: string,
	/**  How the CLI takes it. */
	kind: AttachmentKind,
	/**  The size on disk. A folder counts every file inside it. */
	bytes: number,
	/**  The media type, when `maxd` can tell. */
	mime: string | null,
	/**  Where `maxd` keeps it, as an absolute path on the device. */
	path: string,
	/**
	 *  A small preview of a picture as a `data:` URL, when `maxd` made one
	 *  while it staged the file.
	 */
	thumbnail: string | null,
};

/**  Where an attachment comes from. */
export type AttachmentSource = 
/**  A file or folder on the device `maxd` runs on. */
{ type: "path"; 
/**  Absolute path on the device. */
path: string } | 
/**  Pasted bytes, at most `MAX_INLINE_ATTACHMENT` (8 MiB) once decoded. */
{ type: "bytes"; 
/**  The file name to give it. */
name: string; 
/**  The media type, such as "image/png". */
mime: string; 
/**  The bytes, base64 encoded. */
data: string } | 
/**
 *  A file or folder the `@` menu found in an agent's folder. It stages
 *  on the agent's device, from its container when it runs in one.
 */
{ type: "found"; 
/**  The agent whose folder the search looked in. */
agent: AgentId; 
/**  The path as the search gave it, relative to that folder. */
path: string };

/**  One attempt at a node. */
export type AttemptSpan = {
	/**  When it started. */
	start: Timestamp,
	/**  When it ended, none while it runs. */
	end: Timestamp | null,
	/**  How it ended, once it has. */
	end_status: NodeStatus | null,
	/**  The agent that made it, once bound. */
	agent: AgentId | null,
	/**  When it last began waiting on you, while it still does. */
	waiting_since?: Timestamp | null,
};

/**  Your answer to an event. */
export type AttentionAnswer = 
/**  Picks one of the event's options. */
{ type: "option"; 
/**  An [`AttentionOption::id`] from the event. */
id: string } | 
/**  A typed answer. */
{ type: "text"; 
/**  What you typed. */
text: string } | 
/**
 *  Answers to an agent's questions, as a
 *  [`crate::timeline::ItemBody::Question`] asks them.
 */
{ type: "questions"; 
/**  One for each question you answered. */
answers: QuestionAnswer[] } | 
/**
 *  Turns the request down without an answer and ends the turn, as Esc
 *  does in the CLI, so a message you queued starts the next turn. Its
 *  item ends [`crate::timeline::ItemStatus::Declined`] with nothing
 *  decided or answered. A `maxd` from before
 *  [`crate::message::DISMISS_SINCE`] can't read it.
 */
{ type: "dismiss" };

/**  Something an agent needs from you. */
export type AttentionEvent = {
	/**  Stable, so a notification can open the event days later. */
	id: AttentionId,
	/**  The agent asking. */
	agent: AgentId,
	/**  What it's asking for. */
	kind: AttentionKind,
	/**  One line for the notification and the inbox. */
	summary: string,
	/**  The answers you can pick, in order. */
	options: AttentionOption[],
	/**  Whether a typed answer is allowed as well as the options. */
	accepts_text: boolean,
	/**  When the agent asked. */
	created_at: Timestamp,
	/**
	 *  When the question stops mattering, such as when the CLI's own prompt
	 *  times out.
	 */
	expires_at: Timestamp | null,
};

/**  Something an agent needs from you, such as a permission prompt. */
export type AttentionId = string;

/**  What kind of attention an agent needs. */
export type AttentionKind = 
/**  Asks to run a tool, such as a shell command or a file edit. */
"permission" | 
/**  Asks you a question. */
"question" | 
/**  Finished a turn. */
"done" | 
/**  Stopped on an error. */
"error";

/**  One answer you can pick. */
export type AttentionOption = {
	/**  Sent back in [`AttentionAnswer::Option`]. */
	id: string,
	/**  Shown on the button. */
	label: string,
	/**
	 *  What the agent says this option does, where it says: `allow_once`,
	 *  `allow_always`, `reject_once` or `reject_always`. It decides over the
	 *  label, which can say anything. An older peer leaving it out reads as
	 *  not said, and the id and label decide.
	 */
	kind?: string | null,
};

/**  A short label on a node, such as a tier or a chunk count. */
export type Badge = {
	/**  What it says. */
	text: string,
	/**  How it reads. */
	tone: Tone,
};

/**  The address a listening socket is bound to. */
export type BindAddress = 
/**  127.0.0.1 or ::1, so only the machine itself reaches it. */
{ type: "loopback" } | 
/**  0.0.0.0 or ::, so every interface reaches it. */
{ type: "any" } | 
/**  One other address. */
{ type: "address"; 
/**  The address, such as "10.0.3.15". */
ip: string };

/**
 *  The boot a device or container is on.
 * 
 *  Linux reads it from `/proc/sys/kernel/random/boot_id` and macOS from
 *  `kern.bootsessionuuid`. A new value means the machine restarted since it
 *  was last seen. Incus containers get a fresh one each time they start. The
 *  value is opaque, so it's a string rather than a UUID.
 */
export type BootId = string;

/**  A `maxd` build the app carries. */
export type BundledBuild = {
	/**  The Rust target it runs on. */
	target: string,
	/**  Its build: the first 16 hex characters of its sha256. */
	build: string,
	/**
	 *  Whether a signed release manifest came with it. A build from source
	 *  has none, and goes out only once you agree to send it unsigned.
	 */
	signed: boolean,
};

/**
 *  What a device does beyond agents in folders. A client hides what a
 *  device can't do.
 */
export type Capabilities = {
	/**  Takes uploads and serves downloads, per A-14. */
	transfers: boolean,
	/**  Forwards ports from its agents, per N-6. */
	tunnels: boolean,
	/**  Creates and runs container workspaces through Incus, per W-1. */
	workspaces: boolean,
	/**
	 *  Checks its GitHub App when asked, with `CheckGithubApp`. A `maxd`
	 *  from before it leaves this out, and reads as false.
	 */
	github_checks?: boolean,
	/**
	 *  Keeps its agents' inboxes and takes `SetInbox`. A `maxd` from before
	 *  it leaves this out, and reads as false.
	 */
	inbox?: boolean,
	/**
	 *  Opens SSH sessions with its container workspaces' guests, with
	 *  `GuestSshOpen` and `SetGuestSshKey`, for an editor's Remote-SSH. A
	 *  `maxd` from before it leaves this out, and reads as false.
	 */
	guest_ssh?: boolean,
	/**
	 *  Lists, fetches and places a checkout's ignored files, and clones
	 *  projects into folders, for copying a project to another device. A
	 *  `maxd` from before it leaves this out, and reads as false.
	 */
	copy?: boolean,
	/**
	 *  Answers `ReadLoad` and `ReadDiagnostics`. A `maxd` from before it
	 *  leaves this out, and reads as false.
	 */
	load?: boolean,
	/**
	 *  Installs a new `maxd` or guest binary with `InstallUpdate`. A `maxd`
	 *  from before it leaves this out, and reads as false.
	 */
	updates?: boolean,
	/**
	 *  Reports its agent CLIs and updates them with `UpdateTools`. A `maxd`
	 *  from before it leaves this out, and reads as false.
	 */
	tools?: boolean,
	/**
	 *  Runs the agent tools, keeps permissions and access keys, and takes
	 *  `CallTool`, `AuthKey`, `GrantPermission`, `RevokePermission`,
	 *  `ListPermissions`, `MintKey` and `ListKeys`. A `maxd` from before it
	 *  leaves this out, and reads as false.
	 */
	agent_tools?: boolean,
	/**
	 *  Runs scheduled tasks and their webhooks, publishes
	 *  [`crate::tasks::DeviceTasks`], and takes `SaveTask`, `DeleteTask`,
	 *  `RunTaskNow`, `SetHookOn`, `RotateHookToken`, `SetHookSecret`,
	 *  `SetHookAddress`, `ListRuns` and `ListDeliveries`. A `maxd` from before it leaves this
	 *  out, and reads as false.
	 */
	scheduled_tasks?: boolean,
	/**
	 *  Links to other devices' `maxd` for agent calls, keeps its own SSH
	 *  key, and takes `PeerKey`, `AuthorizePeer`, `RevokePeer` and
	 *  `SetPeerBook`. A `maxd` from before it leaves this out, and reads as
	 *  false.
	 */
	peers?: boolean,
	/**
	 *  Runs local ACP commands, publishes [`crate::acp::AcpAgent`], and
	 *  takes `SetAcpAgent` and `DeleteAcpAgent`. A `maxd` from before it
	 *  leaves this out, and reads as false.
	 */
	acp_agents?: boolean,
	/**
	 *  Watches the PRs its agents link to and answers `ListPulls`,
	 *  `GetPull`, `PullFiles`, `PullComments`, `PullChecks`, `PullsDue`,
	 *  `LinkPull` and `UnlinkPull`. A `maxd` from before it leaves this
	 *  out, and reads as false.
	 */
	pulls?: boolean,
	/**
	 *  Can hold your GitHub sign-in, with `BeginGithubSignIn` and
	 *  `CancelGithubSignIn`, and merges and approves with `PullAction`. A
	 *  `maxd` from before it leaves this out, and reads as false.
	 */
	github_user?: boolean,
	/**
	 *  Offers test hosts and leases, publishes `TestHost` and `TestLease`,
	 *  and takes `CheckTestHosts`, `BuildTestHost`, `ResetTestHost`,
	 *  `EndLease` and `ReadLeaseScreen`. A `maxd` from before it leaves
	 *  this out, and reads as false.
	 */
	test_hosts?: boolean,
	/**
	 *  Follows its projects' workflow runs, publishes `WorkflowRun`, and
	 *  takes `OpenWorkflow`, `CloseWorkflow` and `NodeDetail`. A `maxd`
	 *  from before it leaves this out, and reads as false.
	 */
	workflows?: boolean,
	/**
	 *  Reads its `maxhq-host.toml`, publishes `HostReport`, and takes
	 *  `CheckHost` and `ApplyHost`. A `maxd` from before it leaves this
	 *  out, and reads as false.
	 */
	host_spec?: boolean,
	/**
	 *  Takes `ListSnapshots` and `RestoreSnapshot` for its container
	 *  workspaces. A `maxd` from before it leaves this out, and reads as
	 *  false.
	 */
	snapshots?: boolean,
	/**
	 *  Moves workspaces the old scripts made into MaxHQ, publishes `Move`,
	 *  and takes `PlanMove`, `RunMoveStep`, `MoveBack` and `RetireMove`. A
	 *  `maxd` from before it leaves this out, and reads as false.
	 */
	moves?: boolean,
	/**
	 *  Installs and removes tools itself, publishes `AcpRegistry`, and
	 *  takes `InstallTool`, `RemoveTool`, `InstallAcpAgent` and
	 *  `AcceptLicence`. A `maxd` from before it leaves this out, and reads
	 *  as false.
	 */
	tool_installs?: boolean,
	/**
	 *  Keeps skills for its projects, publishes `SkillLibrary`,
	 *  `ProjectSkills` and `SkillProposal`, and takes the skills requests
	 *  and uploads to its skill store. A `maxd` from before it leaves this
	 *  out, and reads as false.
	 */
	skills?: boolean,
	/**
	 *  Pairs phones and pushes to them, publishes `Phone` and `PhoneBook`,
	 *  and takes the phone requests, first frames and `SetApnsKey`. A
	 *  `maxd` from before it leaves this out, and reads as false.
	 */
	phones?: boolean,
	/**
	 *  Takes `SkillsTakeLibrary` and `SkillSourcePush`, and says which of
	 *  its library's git sources have commits not pushed. A `maxd` from
	 *  before it leaves this out, and reads as false.
	 */
	library_moves?: boolean,
	/**
	 *  Takes `elsewhere` on `SkillProposalDiff`, and works out where a
	 *  proposal goes from its library. A `maxd` from before it leaves this
	 *  out, and reads as false.
	 */
	proposal_targets?: boolean,
	/**
	 *  Takes a `Prove` with the device's own key on a link from another
	 *  device, and serves the link only once it has one. A `maxd` from
	 *  before it leaves this out, and reads as false.
	 */
	peer_proofs?: boolean,
	/**
	 *  Holds terminals for its agents, publishes
	 *  [`crate::terminal::Terminal`], and takes the terminal requests and
	 *  frames. A `maxd` from before it leaves this out, and reads as false.
	 */
	terminals?: boolean,
};

/**  One change in a delta. */
export type Change = 
/**  Adds the entity, or replaces the one with the same key. */
{ op: "upsert"; 
/**  The entity as it is now. */
value: Entity } | 
/**  Removes the entity, if it's there. */
{ op: "remove"; 
/**  The entity to remove. */
key: EntityKey };

/**  How one check stands. */
export type CheckState = 
/**  It passed. */
"passing" | 
/**  It failed. */
"failing" | 
/**  It still runs, or hasn't started. */
"pending" | 
/**  It was skipped or ended neutral. */
"skipped";

/**  Where one checkout of a project stands against its lock. */
export type CheckoutSkills = {
	/**  The checkout's absolute path on the device. */
	path: string,
	/**  Whether it has the lock's skills. */
	applied: boolean,
	/**  The skills whose copies changed since they landed. */
	drift: string[],
	/**  Whether its running agents need a restart to see the skills. */
	needs_restart: boolean,
	/**
	 *  Where its devflow pack stands, while the lock has one or someone
	 *  else's is there. A `maxd` from before it leaves this out.
	 */
	pack?: PackState | null,
	/**
	 *  The links in the checkout, as paths in it, that lead out of it and
	 *  so stopped skills landing through them. A `maxd` from before it
	 *  leaves this out.
	 */
	outside?: string[],
};

/**  How a PR's checks stand, all of them together. */
export type ChecksState = 
/**  Every check passed. */
"passing" | 
/**  At least one failed. */
"failing" | 
/**  None failed and some still run. */
"pending" | 
/**  The PR has no checks. */
"none" | 
/**
 *  The GitHub App can't read checks, because its installation hasn't
 *  accepted the read permissions.
 */
"unknown";

/**
 *  One side of the question: a link, where it's reached and what it was
 *  seen with.
 */
export type ClaimedLink = {
	link: LinkId,
	name: string,
	/**  The hosts it's reached at, in the order they're tried. */
	addresses: string[],
	/**
	 *  Its host keys' fingerprints, such as `ED25519 SHA256:...`: those
	 *  its setup brought, or else those your own `known_hosts` has for it.
	 */
	fingerprints: string[],
	/**
	 *  When it first reached the device, or for the link that waits, when
	 *  it first named it.
	 */
	first_seen: Timestamp | null,
};

/**  Where a CLI login stands, from [`ActionOutcome::CliLoginState`]. */
export type CliLoginState = 
/**  The CLI waits for you to sign in. */
{ state: "waiting" } | 
/**  The CLI stored the login. */
{ state: "signed_in" } | 
/**  The login ended without signing in. */
{ state: "failed"; 
/**  Why, for a person to read. */
message: string };

/**  The first message a client sends. */
export type ClientHello = {
	/**  The versions the client speaks. */
	protocol: ProtocolRange,
	/**  The program connecting. */
	client: ClientInfo,
	/**
	 *  Stays the same across the client's reconnects, so answers it sent
	 *  before a drop are still its own.
	 */
	client_id: ClientId,
	/**  What kind of client connects. Left out, it's the app. */
	role?: ClientRole,
};

/**  A client connection, such as the desktop app on one Mac. */
export type ClientId = string;

/**  Names the program on the other end, for logs and the device list. */
export type ClientInfo = {
	/**  Such as "maxhq-desktop" or "maxhq-ios". */
	name: string,
	/**  The program's own version. */
	version: string,
};

