/**
 *  Which kind of client a connection is. A connection whose hello leaves
 *  it out is the app's.
 */
export type ClientRole = 
/**  The app, with every right. */
"app" | 
/**  `maxd mcp`, which may send only `AuthKey` and then tool calls. */
"mcp" | 
/**
 *  Another device's `maxd`, which may send only agent calls, wakes and
 *  their answers. Only a connection `maxd proxy --peer` opened has it.
 */
"peer";

/**  How a clone into a folder workspace is going. */
export type CloneProgress = {
	/**  Where the clone is. */
	state: CloneState,
};

/**  What `git clone` is doing, as its progress lines say. */
export type CloneStage = 
/**  Reaching the remote, before git reports anything. */
"connecting" | 
/**  The remote is counting and compressing objects. */
"counting" | 
/**  Receiving objects. */
"receiving" | 
/**  Resolving deltas. */
"resolving" | 
/**  Checking out files. */
"checkout";

/**  Where a clone into a folder workspace is. */
export type CloneState = 
/**  git is cloning. Agents can't start in the folder yet. */
{ state: "cloning"; 
/**  What git is doing. */
stage: CloneStage; 
/**  How far along that stage is, 0 to 100, when git says. */
percent: number | null; 
/**  Whether git has said nothing for 20 s. */
stalled: boolean } | 
/**  The clone failed. Retry it or remove it. */
{ state: "failed"; 
/**  What git said, with credentials taken out of URLs. */
reason: string } | 
/**  You stopped the clone, and its partial folder is gone. */
{ state: "cancelled" };

/**  Why a request failed, in words a window can show as they are. */
export type CommandError = 
/**  Nothing has that ID, such as an agent that just ended. */
{ kind: "not_found"; 
/**  What the request was looking for. */
what: string } | 
/**  The device the request needs isn't connected. */
{ kind: "not_connected"; 
/**  The device's name. */
device: string } | 
/**  Anything else. */
{ kind: "failed"; 
/**  What went wrong. */
message: string };

/**
 *  A shell command an agent may run without asking, which you saved by
 *  answering "Always allow". The `maxd` that runs the agent answers the
 *  agent's own prompt for it in every mode but Plan.
 */
export type CommandRule = {
	/**  The command's words, quoted the way a shell reads them back. */
	command: string,
	/**
	 *  True when only this exact command passes, as with one that
	 *  deletes, moves or reaches the network. False when it's a command
	 *  and its subcommand, such as `git show`, and any arguments pass.
	 */
	exact: boolean,
};

/**
 *  The commands agents may run without asking in one project, as the
 *  device that runs those agents keeps them. A device publishes no list
 *  for a project with no rules.
 */
export type CommandRules = {
	/**  The project. */
	project: ProjectId,
	/**  The device that keeps the rules. */
	device: DeviceId,
	/**  The rules, in the order they were saved. */
	rules: CommandRule[],
};

/**  How far a connection attempt has got. */
export type ConnectStep = 
/**  Opening the transport. */
"dialing" | 
/**  Copying or upgrading `maxd` on the device. */
"installing_maxd" | 
/**  Exchanging hellos. */
"handshake" | 
/**  The device is restarting and the client is waiting for it. */
"waiting_for_reboot" | 
/**
 *  The device waits for you to let this app's key in from another
 *  device, and the connection stays up meanwhile.
 */
"waiting_for_approval";

/**  What a card that asks for your consent lays out. */
export type Consent = {
	/**  What's asked for, as the card's title. */
	title: string,
	/**  What could happen, and to what, in a sentence or two. */
	risk: string,
	/**
	 *  What changed since you last allowed it, one line each, or none the
	 *  first time.
	 */
	changes: string[],
	/**
	 *  The details to judge it by, such as the container an agent runs in,
	 *  in order. A peer that leaves this out has none.
	 */
	facts?: ConsentFact[],
	/**  Each thing it covers, in order. */
	rows: ConsentRow[],
	/**  The box that keeps the answer, when it can be kept. */
	remember: ConsentRemember | null,
};

/**  One labelled detail on a consent card, such as `Container: web`. */
export type ConsentFact = {
	/**  What it is, such as "Container". */
	label: string,
	/**  Its value. */
	value: string,
};

/**  The box on a consent card that keeps your answer. */
export type ConsentRemember = {
	/**
	 *  Sent back as a [`QuestionAnswer::id`] with the box's label when it's
	 *  ticked.
	 */
	id: string,
	/**  Shown beside the box. */
	label: string,
	/**
	 *  The line shown once the box is ticked: what it keeps, and where in
	 *  Settings to change it later.
	 */
	settings: string,
};

/**  One thing a consent card covers, such as a variable and its value. */
export type ConsentRow = {
	/**  The heading it sits under, such as the workflow that names it. */
	group: string,
	/**  Its name. */
	name: string,
	/**  Its value. */
	value: string,
	/**
	 *  Whether the value looks like a secret, so a client hides it until you
	 *  ask to see it.
	 */
	secret: boolean,
	/**  What it can do beyond the plain, when it can do more. */
	warning: string | null,
	/**
	 *  Whether it replaces something MaxHQ set itself, so the warning is
	 *  the strongest kind.
	 */
	strong: boolean,
};

/**  What one container workspace has used in all, as Incus counts it. */
export type ContainerUse = {
	/**  The workspace. */
	workspace: WorkspaceId,
	/**  CPU time since it started, in nanoseconds. */
	cpu_ns: number,
	/**  Memory in use now, in bytes. */
	memory: number,
};

/**  How full an agent's context window is. */
export type ContextUsage = {
	/**  Tokens in the conversation now. */
	used_tokens: number,
	/**  The model's window size. */
	window_tokens: number,
};

/**  Who holds an agent's terminal. */
export type Control = 
/**
 *  You started it in your own terminal. MaxHQ shows its state but can't
 *  type into it, so you answer its prompts there.
 */
"observed" | 
/**  MaxHQ started it and holds its terminal. */
"held";

/**  What a copy of a project made. */
export type CopiedProject = {
	/**  The new workspace. */
	workspace: WorkspaceId,
	/**  How many of the chosen files went in. */
	written: number,
	/**  The chosen files that didn't, and why. */
	failed: PlaceFailure[],
};

/**  Where a copy of a project goes. */
export type CopyTarget = 
/**
 *  A new container workspace on a device, which starts when the
 *  device does, as a new workspace does by default.
 */
{ type: "container"; 
/**  The device whose Incus runs it. */
device: DeviceId; 
/**  The container's name after `mhq-`. The project's name when unset. */
name: string | null } | 
/**  A clone into a new folder on a device's own disk. */
{ type: "folder"; 
/**  The device. */
device: DeviceId; 
/**  The folder the clone goes in, which has to be there already. */
parent: string; 
/**  The new folder's name. */
name: string };

/**  A login or key a device holds. Never carries the secret. */
export type Credential = {
	/**  Stable while the device keeps it. */
	id: CredentialId,
	/**  The device that holds it. */
	device: DeviceId,
	/**  What it is. */
	kind: CredentialKind,
	/**  When the device stored it. */
	stored_at: Timestamp,
	/**  The last thing that went wrong using it, such as a refused token. */
	problem: string | null,
};

/**  A login or key a device holds. */
export type CredentialId = string;

/**  What a [`Credential`] is. */
export type CredentialKind = 
/**  W-5. A setup-token, and the account it gives this device. */
{ type: "claude_token"; 
/**  The Mac account the token was minted for. */
origin: AccountId; 
/**  The token account on this device. */
account: AccountId; 
/**  Your name for it. */
label: string } | 
/**  W-5. This device's own Sign in with ChatGPT session. */
{ type: "chat_gpt"; 
/**  The sign-in account on this device. */
account: AccountId; 
/**  The email OpenAI gave for the session. */
email: string | null } | 
/**  A Cursor user API key, and the account it gives this device. */
{ type: "cursor_key"; 
/**  The key account on this device. */
account: AccountId; 
/**  Your name for it. */
label: string } | 
/**  W-6. The App this device mints installation tokens from. */
{ type: "github_app"; 
/**  GitHub's ID for the App. */
app_id: number; 
/**  The App's URL name, once GitHub has said it. */
slug: string | null; 
/**  Hex SHA-256 of the private key, so you can tell keys apart. */
key_sha256: string; 
/**  The repositories the App's installations reach, as "owner/name". */
repos: string[] } | 
/**
 *  Your own GitHub sign-in, which merges and approves PRs as you. One
 *  device holds it, and the token never leaves that device.
 */
{ type: "github_user"; 
/**  Your GitHub login. */
login: string } | 
/**  The APNs key this device signs its pushes to phones with. */
{ type: "apns"; 
/**  Apple's ID for the key, from the `.p8` file's name. */
key_id: string; 
/**  The Apple developer team the key belongs to. */
team_id: string };

/**  The days of the week a task runs on. None means every day. */
export type Days = Weekday[];

/**  How an approval ended: the option picked, or typed text. */
export type Decided = {
	/**  The answer that won. */
	answer: AttentionAnswer,
	/**  The client that sent it, or none when you answered in the CLI itself. */
	by: ClientId | null,
	/**  When the answer arrived. */
	at: Timestamp,
};

/**  How a message you sent reached the agent. */
export type Delivery = 
/**  The agent has it. */
"sent" | 
/**  Waiting for the current turn to end. */
"queued" | 
/**  Went into the running turn. */
"steer" | 
/**  You took it back before it was sent. */
"cancelled";

/**  What came of a delivery. */
export type DeliveryOutcome = 
/**  It queued a run. */
"accepted" | 
/**  It queued a run, which then failed to start. */
"dispatch_failed" | 
/**  Its replay key was seen in the last 7 days. */
"duplicate" | 
/**  It joined an open coalesce window. */
"coalesced" | 
/**  Its signature didn't check out. */
"rejected_signature" | 
/**  The task is paused. */
"disabled" | 
/**  The task had too many requests this minute or runs today. */
"rate_limited" | 
/**  It was older than the task takes, or held too long. */
"expired" | 
/**  A filter didn't match. */
"filtered" | 
/**  The prompt it made was too long. */
"prompt_too_long" | 
/**  Too many runs were waiting. */
"queue_full" | 
/**  The target's device is offline, and the request waits for it. */
"held" | 
/**  The target's device is offline, and the hook doesn't hold requests. */
"target_offline";

/**  The changes from one version of the state to the next. */
export type Delta = {
	/**  The version after these changes, one more than the version before. */
	seq: Seq,
	/**  Applied in order. One this build can't read is left out. */
	changes: Change[],
};

/**  What an agent takes along from the device it leaves. */
export type Departure = {
	/**  The name of the device it leaves. */
	device: string,
	/**  Its name. */
	title: string,
	/**  The permission mode it ran in. */
	mode: PermissionMode,
	/**  The effort level it ran at, if its vendor has one. */
	effort?: string | null,
	/**
	 *  The summary of its conversation that the new agent starts from, or
	 *  none when there was nothing to carry.
	 */
	brief?: string | null,
};

/**  One list in a node's detail, such as the files it touched. */
export type DetailList = {
	/**  What the list is. */
	label: string,
	/**  What's in it. */
	items: string[],
};

/**  A machine that runs `maxd`, as `maxd` describes itself. */
export type Device = {
	/**  Assigned when `maxd` is installed, and kept across restarts. */
	id: DeviceId,
	/**  The host name, unless you renamed the device. */
	name: string,
	/**  The operating system, as Rust's `std::env::consts::OS` names it. */
	os: string,
	/**  Changes on every restart. */
	boot_id: BootId,
	/**  The `maxd` version running there. */
	maxd_version: string,
	/**
	 *  Set while the device winds down for a restart, per A-11. A client
	 *  that loses the device before this keeps retrying every 2 seconds.
	 */
	winding_down_until: Timestamp | null,
	/**
	 *  What Incus offers for container workspaces. Unset on a device
	 *  without Incus.
	 */
	workspace_host: WorkspaceHost | null,
	/**
	 *  The first 16 hex characters of the sha256 of the running `maxd`. A
	 *  `maxd` from before builds leaves this out.
	 */
	build?: string | null,
	/**
	 *  The Rust target `maxd` was built for, such as
	 *  `x86_64-unknown-linux-musl`. A `maxd` from before builds leaves this
	 *  out.
	 */
	target?: string | null,
};

/**  A machine that runs `maxd`. */
export type DeviceId = string;

/**  A client's connection to one device's `maxd`. */
export type DeviceLink = {
	/**  Assigned when you add the device to the client. */
	id: LinkId,
	/**  Your name for the device, or its SSH host until you rename it. */
	name: string,
	/**  The device's ID, once its `maxd` has answered a hello. */
	device: DeviceId | null,
	/**  How the client reaches it, or the route it tries first while down. */
	route: Route,
	/**
	 *  Every route you set for the device, in your order. Empty for a
	 *  device with only `route`.
	 */
	routes?: RouteChoice[],
	/**  Where the connection stands now. */
	state: LinkState,
	/**
	 *  The network the route goes over, once the client has worked it
	 *  out. Unset means a plain network path with nothing to watch.
	 */
	network: NetworkId | null,
	/**
	 *  The overlay network's view of the device, when the device is a peer
	 *  on one. It answers whether the device is up before SSH can.
	 */
	peer: Peer | null,
	/**
	 *  The SSH hosts the route passes through first, nearest first, from a
	 *  `ProxyJump` or the host a `ProxyCommand` dials. A device behind a
	 *  host shares that host's problems.
	 */
	via: string[],
	/**
	 *  What the device does, from its last hello. Unset until it has
	 *  answered one, and kept while the link is down.
	 */
	capabilities: Capabilities | null,
	/**
	 *  The newest protocol version the device's `maxd` speaks, from its
	 *  last hello. Unset and kept like `capabilities`.
	 */
	protocol?: number | null,
	/**
	 *  The protocol versions the device's `maxd` speaks, when its last
	 *  hello found none in common with this client's. Kept while the link
	 *  is down, and unset once a hello agrees.
	 */
	protocol_mismatch?: ProtocolRange | null,
	/**
	 *  The agents with inbox changes waiting in the app's outbox to go out
	 *  through this link, in ID order. The client leaves it empty, and the
	 *  app's view fills it in.
	 */
	waiting: AgentId[],
	/**
	 *  The device this link's hello named while it waits for you to say
	 *  whether that's really the device, because another link already
	 *  knows it. `device` stays unset until you do, so nothing goes to the
	 *  device through this link. The client leaves it unset, and the app's
	 *  view fills it in.
	 */
	claim?: LinkClaim | null,
};

