/**  Settings `maxd` keeps for its device. */
export type DeviceSettings = {
	/**  The device these settings are for. */
	device: DeviceId,
	/**  The mode for new agents started without one. */
	default_permission: PermissionMode,
	/**
	 *  The Incus network new container workspaces join, one of
	 *  [`WorkspaceHost::networks`].
	 */
	workspace_network: string | null,
	/**
	 *  The Incus storage pool new container workspaces live on, one of
	 *  [`WorkspaceHost::pools`].
	 */
	workspace_pool: string | null,
	/**
	 *  U-8. Days an agent sits idle before auto-settle settles it, from 1 to
	 *  90, or 0 for never. A `maxd` from before inboxes leaves this out.
	 */
	auto_settle_days?: number,
	/**  Snoozes an agent that hits a usage limit until the limit resets. */
	snooze_at_limit?: boolean,
	/**
	 *  Whether a Claude Code agent whose turn a usage limit cut off gets a
	 *  message to carry on once the limit resets. It's the default for each
	 *  agent, which [`Inbox::continue_at_limit`] can turn on or off. A
	 *  `maxd` from before this leaves it out, which reads as off.
	 */
	continue_claude_at_limit?: boolean,
	/**  The same for Codex agents. */
	continue_codex_at_limit?: boolean,
	/**
	 *  The effort level new Claude Code agents start at, or none for each
	 *  model's [`ModelChoice::default_effort`]. A `maxd` from before
	 *  [`crate::message::EFFORT_SINCE`] leaves it out.
	 */
	claude_effort?: string | null,
	/**  The same for Codex agents. */
	codex_effort?: string | null,
	/**  How readily new agents go to this device when you don't pick one. */
	placement?: Placement,
	/**
	 *  The CLIs on the device itself that MaxHQ may update. Empty means you
	 *  update them yourself. CLIs in container workspaces MaxHQ made update
	 *  on their own.
	 */
	tool_updates?: Tool[],
	/**
	 *  Lets a Mac's `maxd` read the Cursor CLI's login from the Keychain
	 *  and ask Cursor for the plan's usage this month. Off unless you turn
	 *  it on.
	 */
	cursor_usage?: boolean,
	/**
	 *  When a Mac's `maxd` keeps it from idling to sleep. Other systems
	 *  ignore it.
	 */
	keep_awake?: KeepAwake,
	/**  The test hosts this device offers. */
	test_hosts?: TestHostSettings,
	/**
	 *  Whether this device keeps the skill library. None leaves it to the
	 *  default, which is that a Mac keeps it and other devices don't.
	 */
	skill_library?: boolean | null,
	/**
	 *  Whether phones reach this device over the network, and on which
	 *  port.
	 */
	network?: NetworkAccessSettings,
	/**
	 *  Minutes an agent sits idle before `maxd` stops its CLI to free the
	 *  memory, or 0 for never. The agent stays as it is and its CLI starts
	 *  again for the next message. A `maxd` from before this leaves it out.
	 */
	idle_release_minutes?: number,
	/**
	 *  How many of each agent's newest items `maxd` keeps in memory, from
	 *  [`MEMORY_ITEMS`]. The rest wait on disk until a client scrolls back.
	 *  A `maxd` from before this leaves it out.
	 */
	memory_items?: number,
	/**
	 *  How much of each agent's history `maxd` keeps, in MiB from
	 *  [`HISTORY_MIB`], or 0 for no limit. Past it the oldest items leave
	 *  the agent's timeline on this device, though the CLI's own history
	 *  keeps them. A `maxd` from before this leaves it out.
	 */
	history_mib?: number,
	/**
	 *  Whether this device takes a Claude setup-token: stores it and hands
	 *  it to Claude Code agents when they start. It's meant for personal
	 *  use and is off unless you turn it on; signing in with `claude` on
	 *  the device needs no token. A `maxd` from before this leaves it out,
	 *  and always takes one.
	 */
	claude_setup_token?: boolean,
	/**
	 *  Whether terminals this device opens give zsh, bash and fish hooks
	 *  that mark each prompt and command, so MaxHQ can tell commands
	 *  apart. Off starts shells as their own startup files say. It applies
	 *  to shells opened after it changes. A `maxd` from before
	 *  [`crate::message::SHELL_MARKS_SINCE`] leaves it out and adds no
	 *  hooks.
	 */
	shell_integration?: boolean,
	/**
	 *  Whether agents on this device may list and read other agents, here
	 *  and on linked devices, without a permission. Starting, messaging,
	 *  stopping and moving agents still need one. Off, an agent reads only
	 *  agents you attached or quoted, unless its permission reaches them.
	 *  A `maxd` from before [`crate::message::READ_RIGHTS_SINCE`] leaves
	 *  it out and lets agents read only what they're allowed.
	 */
	read_other_agents?: boolean,
};

/**  The tasks a device holds, and whether its webhooks can be reached. */
export type DeviceTasks = {
	/**  The device. */
	device: DeviceId,
	/**  Its tasks. */
	tasks: Task[],
	/**
	 *  How its webhooks are reached. A `maxd` from before the choice
	 *  leaves this out, and reads as this device only.
	 */
	address?: HookAddress,
	/**
	 *  The port its hook listener takes requests on, for a tunnel or proxy
	 *  to point at.
	 */
	port?: number | null,
	/**  Whether they can be reached there. */
	funnel: FunnelState,
	/**
	 *  Why some of its tasks can't run now, such as the GitHub App missing
	 *  from a task's repository.
	 */
	problems: TaskProblem[],
	/**
	 *  How each enabled GitHub events task hears of events. A `maxd` from
	 *  before webhooks leaves this out.
	 */
	webhooks?: TaskWebhook[],
};

/**
 *  The tools on one device: on the device itself and in each container
 *  workspace MaxHQ made. The agent CLIs, the helpers MaxHQ installs, and
 *  ACP registry agents.
 */
export type DeviceTools = {
	/**  The device. */
	device: DeviceId,
	/**  One entry for each CLI in each place. */
	tools: ToolInfo[],
};

/**  How a signature's digest is written. */
export type DigestEncoding = 
/**  Lowercase hex. */
"hex" | 
/**  Standard base64. */
"base64";

/**  A device's dispatcher, as its `maxd` publishes it. */
export type Dispatcher = {
	/**  The device it runs on. */
	device: DeviceId,
	/**
	 *  The workspace of its own folder. Its agents run there, and clients
	 *  leave them out of the sidebar.
	 */
	workspace: WorkspaceId,
	/**
	 *  The agent of the conversation now. None before the first request,
	 *  and after you start a new conversation.
	 */
	agent: AgentId | null,
	/**  The plan it submitted, until you confirm or dismiss it. */
	plan: Plan | null,
};

/**  Where a download landed. */
export type Downloaded = {
	/**  The file or folder on this machine, under `~/Downloads/MaxHQ`. */
	path: string,
};

/**  One edge of a run's shape: `to` needs `from`. */
export type EdgeShape = {
	/**  The node needed. */
	from: string,
	/**  The node that needs it. */
	to: string,
};

/**  One editor, as the app shows it. */
export type EditorChoice = {
	/**  What [`crate::Request::OpenInEditor`] calls it. */
	id: string,
	/**  What the menu calls it. */
	label: string,
};

/**
 *  The editors this machine has, for the menu, and every one MaxHQ knows,
 *  for the default editor setting.
 */
export type Editors = {
	/**  In the order the menu lists them. */
	available: EditorChoice[],
	/**  Every entry of [`EDITORS`], installed or not, in the same order. */
	known: EditorChoice[],
};

/**
 *  One skill a CLI sees from a place, as the scan finds it. The fields up
 *  to `user_invocable` follow a provider's own skill shape.
 */
export type EffectiveSkill = {
	/**  Its name. */
	name: string,
	/**  Its description. */
	description: string | null,
	/**  Its `SKILL.md` path on the device. */
	path: string,
	/**  The CLI's own word for where it is, when it has one. */
	scope: string | null,
	/**  Whether the CLI offers it. */
	enabled: boolean,
	/**  The name to show, when it differs. */
	display_name: string | null,
	/**  A shorter description, when it has one. */
	short_description: string | null,
	/**  Only you can call it, so the composer offers it as a command. */
	user_invocation_only: boolean | null,
	/**  Whether you can call it; when false only agents can. */
	user_invocable: boolean | null,
	/**  Where the CLI finds it. */
	place: SkillPlace,
	/**  The CLI that sees it. */
	cli: Vendor,
	/**  What the scan noticed, if anything. */
	mark: SkillMark | null,
};

/**  What came of the probe that tries what a container mustn't reach. */
export type EgressCheck = 
/**  The probe hasn't run yet. */
{ state: "not_run" } | 
/**  Nothing W-7 blocks answered. */
{ state: "passed"; 
/**  When the probe ran. */
at: Timestamp } | 
/**  Something W-7 blocks answered. Agents won't start until a check passes. */
{ state: "failed"; 
/**  When the probe ran. */
at: Timestamp; 
/**  Each target that answered, such as "192.168.1.1:443". */
reached: string[] };

