/**
 *  One command you ran in an agent's session, as a block in its card. It
 *  has the fields of a `UserRun` card, so the app shows it the same way.
 */
export type SessionBlock = {
	/**
	 *  The block's ID. A session counts its commands from 1 across all
	 *  its cards, so no two of its blocks share one.
	 */
	id: number,
	/**  The command line, as typed after the `!`. */
	command: string,
	/**  The folder it started in, as the device writes it. */
	cwd: string,
	/**
	 *  The folder the shell was in once it ended, when the command moved
	 *  it, as the device writes it.
	 */
	cwd_after: string | null,
	/**
	 *  Whether it's kept from the agent: you ran it with `!!`, or switched
	 *  it to private.
	 */
	private: boolean,
	/**
	 *  Whether it still runs, and its exit code once it ended. A session
	 *  reports no signals, and a command it lost track of, such as one
	 *  running when its shell ended, ends with no code.
	 */
	process: TerminalStatus,
	/**  When it started. */
	started_at: Timestamp,
	/**  How long it ran, once it ended. */
	duration_ms: number | null,
	/**  How many lines it wrote, once it ended. */
	lines: number,
	/**
	 *  What it wrote, once it ended, styled as a `UserRun`'s output is. A
	 *  password you sent at a prompt shows as the prompt followed by
	 *  ` 🔒 sent`, never as what you typed.
	 */
	output: string,
	/**
	 *  Whether `output` holds only the last part of what it wrote, or the
	 *  terminal no longer held its start.
	 */
	output_truncated: boolean,
	/**  How many passwords you sent at prompts that hid what you typed. */
	secret_prompts: number,
	/**
	 *  Where the shell's mark for the command's start begins, with its
	 *  output right after, as an offset in all the session's terminal
	 *  printed. A client follows the block live from there with
	 *  [`crate::ClientMessage::TerminalAttach`], whose `after` is then one
	 *  less. None until the shell marks the command's start.
	 */
	start: number | null,
};

/**  A process kept alive by `maxd hold`. */
export type SessionId = string;

/**  One command in an [`InlineRef::Session`]. */
export type SessionRefBlock = {
	/**  The command line, as typed after the `!`. */
	command: string,
	/**  The folder it started in, as the device writes it. */
	cwd: string,
	/**
	 *  The folder the shell was in once it ended, when the command moved
	 *  it.
	 */
	cwd_after?: string | null,
	/**
	 *  Its exit code, or none while it runs or when the session lost track
	 *  of it.
	 */
	exit_code: number | null,
	/**  Whether it still ran when the message went. */
	running: boolean,
	/**  How long it ran, or has run so far, if known. */
	duration_ms: number | null,
	/**  How many lines it wrote in all, which may be more than `text` holds. */
	lines_total: number,
	/**  Its last lines, as plain text. */
	text: string,
};

/**  When and why an agent was settled. */
export type Settled = {
	/**  When. Auto-settle sets it to the agent's last activity. */
	at: Timestamp,
	/**  Who settled it. */
	by: Settler,
};

/**  Who settled an agent. */
export type Settler = 
/**  You did. */
"you" | 
/**  Auto-settle did, after the agent sat idle for the set number of days. */
"auto" | 
/**  Its PR merged. */
({ merged: PullKey }) & { closed?: never } | 
/**  Its PR closed without merging while the agent sat idle. */
({ closed: PullKey }) & { merged?: never };

/**  A host setup offers. */
export type SetupHost = {
	host: string,
	from: SetupHostFrom,
	/**  Its address, when the app knows it apart from the name. */
	address: string | null,
	/**  The link that reaches it already, if any. */
	link: LinkId | null,
};

/**  Where a host setup offers came from. */
export type SetupHostFrom = "ssh_config" | "tailnet";

/**  What a setup is doing. `setup` names the run. */
export type SetupProgress = 
/**  A stage started. */
{ type: "step"; setup: string; step: SetupStep; message: string } | 
/**
 *  A host key ssh hasn't seen waits for your OK. Answer with
 *  `ConfirmHostKey`. Nothing runs on the host before.
 */
{ type: "host_key"; setup: string; host: string; key_type: string; fingerprint: string } | 
/**  Something for you to do there yourself. */
{ type: "hint"; setup: string; step: SetupStep; text: string; command: string } | 
/**  Set up. */
{ type: "done"; setup: string; link: LinkId; device: DeviceId } | 
/**  Stopped. */
{ type: "failed"; setup: string; step: SetupStep; reason: string };

/**  A login to hand a device once it's set up. */
export type SetupSecret = 
/**
 *  A Claude setup-token, as `StoreClaudeToken` takes it. Sending one
 *  turns setup-tokens on for the device first, so the wizard asks you
 *  before it offers one.
 */
{ secret: "claude_token"; origin: AccountId; label: string; token: Secret } | 
/**  A GitHub App, its private key read from `key_path`. */
{ secret: "github_app"; app_id: GithubAppId; key_path: string };

/**  The stages of a setup, as the wizard shows them. */
export type SetupStep = "pick" | "host_key" | "install" | "key" | "handshake" | "secrets";

/**  What one window's panes show, as its page reports it. */
export type Shown = {
	/**  The agent whose pane has focus. Only a window with focus has one. */
	focused: AgentId | null,
	/**
	 *  Every agent whose pane shows: the active pane of each group, docked
	 *  or floating.
	 */
	visible: AgentId[],
};

/**  A Sign in with ChatGPT round that a device started and waits on. */
export type SignInId = string;

/**
 *  An HMAC-SHA256 check on a request's raw body. The secret is set with
 *  [`crate::message::ClientMessage::SetHookSecret`] and never comes back.
 */
export type SignatureCheck = {
	/**  The header with the signature, such as `x-hub-signature-256`. */
	header: string,
	/**  How the digest is written. */
	encoding: DigestEncoding,
	/**  The text before the digest, such as `sha256=`. Empty for none. */
	prefix: string,
	/**  Whether the device holds a secret for it, set by `maxd`. */
	has_secret: boolean,
};

/**
 *  A release's fleet manifest, `maxd-release.json`, and its signature,
 *  `maxd-release.json.sig`, as the release put them beside its binaries.
 */
export type SignedRelease = {
	/**
	 *  The manifest's text: the release's version and the sha256 of each
	 *  `maxd-<target>` it carries.
	 */
	manifest: string,
	/**
	 *  The signature's text: base64 of a minisign signature over the
	 *  manifest's bytes, as `tauri signer sign` writes it.
	 */
	signature: string,
};

/**  What a skill does beyond its instructions, which the app flags. */
export type SkillFlags = {
	/**  It ships scripts. */
	scripts: boolean,
	/**  It sets hooks. */
	hooks: boolean,
	/**  It names `allowed-tools`. */
	allowed_tools: boolean,
};

/**  One skill in a source, at the source's commit. */
export type SkillInfo = {
	/**  Its name, which matches its folder. */
	name: string,
	/**  Its description, from `SKILL.md`. */
	description: string,
	/**  Its folder's hash. */
	tree: TreeHash,
	/**  Its folder's path in the source. */
	path: string,
	/**  The source it's in. */
	source: SkillSourceId,
	/**  What it does beyond its instructions. */
	flags: SkillFlags,
	/**  About how many characters it adds to each CLI's skill listing. */
	listing_chars: number,
};

/**  The library, as the device that holds it publishes it. */
export type SkillLibrary = {
	/**  The device that holds it. */
	device: DeviceId,
	/**  Its sources. */
	sources: SkillSource[],
	/**
	 *  The skills every agent gets globally, which project skills can't be
	 *  named after.
	 */
	always: string[],
	/**
	 *  The library's skill for each of `always` it keeps, which the app
	 *  brings to every other device. One MaxHQ ships isn't here. A `maxd`
	 *  from before it leaves this out.
	 */
	always_skills?: LockedSkill[],
};

/**  The skills a project uses. */
export type SkillLock = {
	/**  Its skills, by name. */
	skills: LockedSkill[],
	/**  Whether the copies are committed to the repo rather than ignored. */
	committed: boolean,
	/**
	 *  The library source its checkouts install as their devflow pack. A
	 *  `maxd` from before it leaves this out, and a lock without one
	 *  leaves it out of the mirror.
	 */
	pack?: SkillPack | null,
};

/**  What the scan noticed about a skill. */
export type SkillMark = 
/**  A global skill of the same name runs instead. */
"shadowed" | 
/**  The same name is in two places with the same tree. */
"same" | 
/**  The same name is in two places with different trees. */
"conflict" | 
/**  Another installer, such as devflow, owns its link. */
"vendored";

/**  A library source a project uses whole, as its devflow pack. */
export type SkillPack = {
	/**  The source. */
	source: SkillSourceId,
	/**  The source commit it was taken at. */
	commit: string,
	/**  The source's whole tree at that commit. */
	tree: TreeHash,
};

/**  Where a CLI finds a skill. */
export type SkillPlace = 
/**  In the project. */
"project" | 
/**  In your global folders. */
"global" | 
/**  In the set MaxHQ keeps global on every device. */
"always" | 
/**  From a plugin. */
"plugin" | 
/**  Shipped with the CLI. */
"system";

/**  A changed skill an agent wrote to its checkout's proposals folder. */
export type SkillProposal = {
	/**  The proposal. */
	id: SkillProposalId,
	/**  The device it was found on. */
	device: DeviceId,
	/**  The project it was found in. */
	project: ProjectId,
	/**  The agent that wrote it, when known. */
	agent: AgentId | null,
	/**  The skill it changes. */
	name: string,
	/**  The tree it started from, none for a new skill. */
	base: TreeHash | null,
	/**  The changed folder's hash. */
	tree: TreeHash,
	/**  The checkout it's in, as an absolute path on the device. */
	checkout: string,
	/**  When it was found. */
	created_at: Timestamp,
	/**  What the changed skill does beyond its instructions. */
	flags: SkillFlags,
	/**  The source the skill comes from, none for a new skill. */
	source: SkillSourceId | null,
};

/**  A changed skill an agent proposes, waiting for you. */
export type SkillProposalId = string;

/**  One source of skills, as the holder keeps it. */
export type SkillSource = {
	/**  The source. */
	id: SkillSourceId,
	/**  What the app calls it. */
	name: string,
	/**  Where its skills come from. */
	kind: SourceKind,
	/**  The branch or tag it fetches, none for a git repo's default. */
	default_ref: string | null,
	/**  Whose it is. */
	trust: SourceTrust,
	/**
	 *  The commit its skills are read at, once fetched. None for a local
	 *  folder.
	 */
	commit: string | null,
	/**  When it was last fetched. */
	fetched_at: Timestamp | null,
	/**  Why the last fetch failed, while it has. */
	problem: string | null,
	/**  Its skills. */
	skills: SkillInfo[],
	/**
	 *  Its whole tree at `commit`, git's files only, when it's a git repo
	 *  with an `install.sh` at its root a project can use as its devflow
	 *  pack. A `maxd` from before it leaves this out.
	 */
	pack?: TreeHash | null,
	/**
	 *  Whether it's a git source with commits its remote doesn't have. A
	 *  `maxd` from before it leaves this out.
	 */
	unpushed?: boolean,
};

/**  A git repo or local folder the skill library takes skills from. */
export type SkillSourceId = string;

/**  The whole state at one sequence number. */
export type Snapshot = {
	/**  The version this snapshot shows. */
	seq: Seq,
	/**
	 *  Every entity, in no particular order. One this build can't read,
	 *  such as a kind from a newer `maxd`, is left out.
	 */
	entities: Entity[],
};

/**  Where a source's skills come from. */
export type SourceKind = 
/**  A git repo the holder clones. */
{ kind: "git"; 
/**  What it clones from. */
url: string } | 
/**  A folder on the holder. */
{ kind: "local"; 
/**  Absolute path on the holder. */
path: string };

/**  Whose a source is, which decides how its updates land. */
export type SourceTrust = 
/**  Yours. Its skills follow updates unless you pin them. */
"own" | 
/**
 *  Someone else's. Its skills are pinned, and an update shows what it
 *  adds before it lands.
 */
"third_party";

/**
 *  What you picked in the spelling menu. Cut, copy and paste go straight
 *  to the focused text through the webview, so they come back as `none`.
 */
export type SpellingChoice = 
/**  The menu closed without a spelling choice. */
{ kind: "none" } | 
/**  Put this word in place of the misspelling. */
{ kind: "replace"; 
/**  The guess you picked. */
word: string } | 
/**
 *  The word is now ignored everywhere in the app until it quits, so
 *  check the text again.
 */
{ kind: "ignored" } | 
/**  The word is now in your macOS dictionary, so check the text again. */
{ kind: "learned" };

/**  The interface labels on the spelling menu. */
export type SpellingMenuLabels = {
	no_guesses: string,
	ignore: string,
	learn: string,
	cut: string,
	copy: string,
	paste: string,
};

/**  Where an editor stands with a container workspace over SSH. */
export type SshIncludeState = 
/**
 *  Your `~/.ssh/config` includes MaxHQ's, so an editor reaches the
 *  workspace as `alias`.
 */
{ type: "included"; alias: string } | 
/**
 *  The app hasn't asked yet. `line` is what it adds at the top of your
 *  `~/.ssh/config` once you say yes.
 */
{ type: "ask"; alias: string; line: string } | 
/**  You said no. `block` is the entry to copy into your own config. */
{ type: "declined"; alias: string; block: string } | 
/**  No editor reaches the workspace now, with why. */
{ type: "unavailable"; reason: string };

/**  One connection through a forward. */
export type StreamId = string;

/**  When [`ClientMessage::TakeOver`] stops the terminal's CLI. */
export type TakeOverMode = 
/**
 *  Once the turn in progress ends, or now when none runs. The action is
 *  done once the wait starts.
 */
"after_turn" | 
/**
 *  Now, cutting off a turn in progress. The action is done once the
 *  session continues here.
 */
"now" | 
/**  Cancels a wait for the turn to end. */
"cancel";

/**  A scheduled task. */
export type Task = {
	/**  The task. */
	id: TaskId,
	/**  The name you gave it. */
	name: string,
	/**
	 *  What the run sends the agent. For a webhook or GitHub events, a
	 *  template that takes values from the request.
	 */
	prompt: string,
	/**  What makes it run. */
	trigger: Trigger,
	/**  The agent each run reaches. */
	target: TaskTarget,
	/**  Whether it runs. A paused task keeps its schedule and its webhook. */
	enabled: boolean,
	/**  The permission each run is checked against, as it stands then. */
	permission: PermissionId,
	/**  Who made it. */
	made_by: Maker,
	/**
	 *  When the timer fires next, set by `maxd`. None for a webhook, GitHub
	 *  events or a paused task.
	 */
	next_run: Timestamp | null,
	/**  How the last run went, set by `maxd`. */
	last_run: RunSummary | null,
	/**
	 *  When `maxd` asked you to approve it, while it waits for you, set by
	 *  `maxd`. A task an agent makes, turns on or changes waits here, off,
	 *  until you approve it on its card or turn it on yourself. A peer
	 *  that leaves this out has none.
	 */
	approval_asked?: Timestamp | null,
};

/**  One request to a webhook, or one GitHub event, and what came of it. */
export type TaskDelivery = {
	/**  The request, or the GitHub event's ID. */
	id: string,
	/**  The task. */
	task: TaskId,
	/**  When it arrived. */
	received: Timestamp,
	/**  The HTTP method. */
	method: string,
	/**  Its content type, if it named one. */
	content_type: string | null,
	/**  How big its body was. */
	body_bytes: number,
	/**  What came of it. */
	outcome: DeliveryOutcome,
	/**  Whether its signature checked out. */
	signature_verified: boolean,
	/**  The template's fields it lacked. */
	missing_fields: string[],
	/**
	 *  The template's free text fields the task doesn't allow, which the
	 *  prompt left out.
	 */
	refused_fields?: string[],
	/**  What went wrong, for a person to read. */
	error: string | null,
};

/**
 *  A scheduled task, which starts or messages an agent on a timer, a
 *  webhook or GitHub events.
 */
export type TaskId = string;

/**  Why a task can't run now. */
export type TaskProblem = {
	/**  The task. */
	task: TaskId,
	/**  Why, in words for the user. */
	reason: string,
	/**  A page that fixes it, such as the GitHub App's permissions. */
	link?: string | null,
};

/**  The agent a task's runs reach. */
export type TaskTarget = 
/**
 *  An agent that already runs. Each run queues the prompt as a message,
 *  which it takes when its turn ends.
 */
{ type: "agent"; 
/**  The device the agent is on. */
device: DeviceId; 
/**  The agent. */
agent: AgentId } | 
/**  A new agent for each run, with the prompt as its first message. */
{ type: "new"; 
/**  The device it starts on. */
device: DeviceId; 
/**  What it should be. `first` and `origin` are set by the run. */
spec: AgentSpec };

/**
 *  How a GitHub events task hears of events: at once through a repository
 *  webhook `maxd` made, or by polling every minute.
 */
export type TaskWebhook = {
	/**  The task. */
	task: TaskId,
	/**
	 *  Whether the webhook delivered a verified request in the last hour,
	 *  so events come at once and polling slows to a backstop.
	 */
	instant: boolean,
	/**  When it last did. */
	last_delivery: Timestamp | null,
};

/**  A terminal one device holds for one agent. */
export type Terminal = {
	/**  The terminal. */
	id: TerminalId,
	/**  The agent whose folder it runs in. */
	agent: AgentId,
	/**  The device whose `maxd` holds it. */
	device: DeviceId,
	/**  What it runs. */
	kind: TerminalKind,
	/**
	 *  Whether you moved this run from the timeline to the drawer, where it
	 *  goes on as a tab. A shell is always a tab there, so it's false.
	 */
	moved: boolean,
	/**
	 *  The tab's name: what the shell set as the window title, or what you
	 *  renamed it to.
	 */
	title: string,
	/**
	 *  The folder it started in, as the device writes it, such as
	 *  `~/code/example-app`.
	 */
	cwd: string,
	/**  Whether it still runs. */
	status: TerminalStatus,
	/**
	 *  Whether a command runs in it: a program other than the shell holds
	 *  its foreground, its shell marked a command that hasn't ended, or a
	 *  `!` run hasn't ended. False while a shell waits at its prompt,
	 *  whatever title it sets there, and when the device doesn't say.
	 */
	busy?: boolean,
	/**
	 *  Whether the OSC 133 in its output are its shell's marks: its holder
	 *  lets through only those with the terminal's nonce, in the plain
	 *  form, and drops any other. False from a holder or device before
	 *  protocol 47, whose output can carry any program's 133, so a client
	 *  takes none as a mark.
	 */
	marks?: boolean,
	/**
	 *  Whether it waits for a password at a prompt that hides what you
	 *  type, so clients offer a secure field.
	 */
	password_prompt: boolean,
	/**  When it started. */
	started_at: Timestamp,
	/**  Its width in cells. */
	cols: number,
	/**  Its height in cells. */
	rows: number,
};

/**
 *  A terminal a device's `maxd` holds: a shell in an agent's terminal
 *  drawer, or a command you ran with `!`.
 */
export type TerminalId = string;

/**  What a terminal runs. */
export type TerminalKind = 
/**  Your login shell, as a tab in the agent's terminal drawer. */
{ type: "shell" } | 
/**
 *  One command you ran with `!`, shown as a card in the timeline until
 *  you move it to the drawer.
 */
{ type: "run"; 
/**  The command line, as typed after the `!`. */
command: string; 
/**
 *  Whether you ran it with `!!`, so its output only goes to the
 *  agent when you attach it to a message.
 */
private: boolean } | 
/**
 *  The agent's session: the one shell its `!` commands share, so `cd`
 *  and `export` carry over. A tab first in the drawer, titled
 *  "Session". An agent has one at most. Since protocol 48: an older
 *  client leaves the whole terminal out.
 */
{ type: "session" };

/**  Whether a terminal's process still runs. */
export type TerminalStatus = 
/**  It runs. */
{ state: "running" } | 
/**  It ended. */
{ state: "exited"; 
/**  The exit code, or none when a signal ended it. */
code: number | null; 
/**  The signal that ended it, if one did. */
signal: number | null };

/**
 *  One kind of test machine on one backend on one device, as that
 *  device's `maxd` publishes it for each kind it hosts.
 */
export type TestHost = {
	/**  The host, from [`host_id`]. */
	id: TestHostId,
	/**  The device it runs on. */
	device: DeviceId,
	/**  What it offers. */
	kind: TestKind,
	/**  What runs it. */
	backend: TestHostBackend,
	/**  Where it stands. */
	state: TestHostState,
	/**
	 *  What the device lacks, as one or two sentences, while it's
	 *  unavailable.
	 */
	setup: string | null,
	/**  Why the last build or reset failed, while it's failed. */
	error: string | null,
	/**  The agent-device version it drives with, once installed. */
	agent_device: string | null,
	/**  When it last went back to a clean state. */
	last_reset: Timestamp | null,
	/**  How many lease requests wait for it. */
	queue: number,
	/**  The VM's size, for a [`TestHostBackend::MacVm`] host that has one. */
	vm: VmSize | null,
};

/**  What runs a test machine, and so what keeps the app under test in. */
export type TestHostBackend = 
/**
 *  An Incus container, `mhq-test-linux`, restored from a snapshot
 *  between leases.
 */
"incus_test" | 
/**  A macOS VM on the Mac, cloned from its base between leases. */
"mac_vm" | 
/**
 *  The Mac's own Simulator, which you opt into. Apps it runs can read
 *  your home folder.
 */
"mac_host" | 
/**
 *  The Android emulator on the device itself, inside the emulator's
 *  own VM, booted from a clean snapshot each lease.
 */
"host_emulator";

/**
 *  A test host: one kind of test machine on one backend on one device,
 *  derived from the three.
 */
export type TestHostId = string;

/**  What a device's `maxd` keeps about the test hosts it offers. */
export type TestHostSettings = {
	/**  The kinds this device hosts. None unless you pick them. */
	kinds?: TestKind[],
	/**
	 *  Lets iOS leases use the Mac's own Simulator. Off unless you turn it
	 *  on.
	 */
	mac_host?: boolean,
	/**  How many macOS VMs may run at once, 1 or [`MAX_VMS`]. */
	max_vms?: number,
	/**  How long a lease lasts when the agent doesn't say, in minutes. */
	default_minutes?: number,
	/**  The longest lease an agent may ask for, in minutes. */
	longest_minutes?: number,
	/**  How long a lease may go without a call before it ends, in minutes. */
	idle_minutes?: number,
};

/**  Where a test host stands. */
export type TestHostState = 
/**
 *  The device lacks something it needs, which [`TestHost::setup`]
 *  says.
 */
"unavailable" | 
/**  It has what it needs, and waits for you to build it. */
"off" | 
/**  It's being built. */
"building" | 
/**  It's ready for a lease. */
"warm" | 
/**  A lease holds it. */
"leased" | 
/**  It's going back to a clean state after a lease. */
"resetting" | 
/**  A build or reset failed, which [`TestHost::error`] says. */
"failed";

/**  A kind of test machine. */
export type TestKind = 
/**  A Linux container. */
"linux" | 
/**  A macOS VM. */
"macos" | 
/**  An iOS Simulator. */
"ios_simulator" | 
/**  An Android emulator. */
"android_emulator";

/**
 *  One holder's time on a test host. The device that hosts it grants it,
 *  and only a caller on that device holds one.
 */
export type TestLease = {
	/**  The lease. */
	id: LeaseId,
	/**  The device that grants and holds it. */
	device: DeviceId,
	/**  The host it's on. */
	host: TestHostId,
	/**  The kind it asked for. */
	kind: TestKind,
	/**  Who holds it, on this device. */
	holder: Actor,
	/**  The permission it was granted under. */
	permission: PermissionId,
	/**  When it was asked for. */
	started_at: Timestamp,
	/**  When its time is up. */
	ends_at: Timestamp,
	/**  When it ends unless another call comes first. */
	idle_ends_at: Timestamp,
	/**  Where it stands. */
	state: LeaseState,
	/**  The Simulator's UDID or the emulator's serial, once ready. */
	target: string | null,
	/**  Why it ended, once it has. */
	ended: LeaseEnd | null,
	/**  Its last commands, oldest first, at most [`RECENT_COMMANDS`]. */
	recent?: LeaseCommand[],
};

/**  `Text` is the message, reasoning or plan text. `Output` is a command's output. */
export type TextField = 
/**  The `text` of a message or reasoning, or the `markdown` of a plan. */
"text" | 
/**  The `output` of a command. */
"output";

/**  A time of day, to the minute. */
export type TimeOfDay = {
	/**  0 to 23. */
	hour: number,
	/**  0 to 59. */
	minute: number,
};

/**  One change to a timeline. */
export type TimelineEvent = 
/**  Adds the item, or replaces the one with its ID. */
{ type: "upsert"; 
/**  The whole item. */
item: TimelineItem } | 
/**  Adds text to the end of one field, for streaming. */
{ type: "append"; 
/**  The item to add to. */
id: ItemId; 
/**  The field to add to. */
field: TextField; 
/**  The text to add. */
text: string } | 
/**  Takes the item out, such as a queued message you cancelled. */
{ type: "remove"; 
/**  The item to take out. */
id: ItemId };

/**  What a find across a timeline found. */
export type TimelineFind = {
	/**  How many matches the whole timeline has. */
	total: number,
	/**  The active match's index among all of them. 0 when there are none. */
	active: number,
	/**  The active match. None when there are no matches. */
	found: FindMatch | null,
	/**
	 *  Up to 17 items with matches around the active one's, in the order
	 *  next steps through them: the active item 9th, wrapping round. All of
	 *  them, oldest first, when 17 or fewer items match.
	 */
	near: FindItem[],
};

/**
 *  One entry in a timeline. On the wire the body's fields sit beside the
 *  item's own, with `kind` naming the body.
 */
export type TimelineItem = {
	/**  Stable for the life of the item, so a later event can replace it. */
	id: ItemId,
	/**  The agent whose conversation this is. */
	agent: AgentId,
	/**  The turn the item came in, when the CLI numbers turns. */
	turn: TurnId | null,
	/**  The item this one belongs under, such as a command an approval is for. */
	parent: ItemId | null,
	/**  Position in the timeline, from 0, assigned by maxd. Never reused. */
	ordinal: number,
	/**  Where the item is in its life. */
	status: ItemStatus,
	/**  When the item began, if the CLI said. */
	started_at: Timestamp | null,
	/**  When the item ended, if it has and the CLI said. */
	completed_at: Timestamp | null,
} & ItemBody;

/**  One timeline update, as a window's channel carries it. */
export type TimelineMessage = {
	/**  The agent whose timeline changed. */
	agent: AgentId,
	/**  What changed. */
	update: TimelineUpdate,
	/**
	 *  Set for events that just happened on the device, as opposed to a
	 *  reset, a page, or what an open or a reconnect caught up on.
	 */
	live: boolean,
};

/**  What a client gets for one open timeline. */
export type TimelineUpdate = 
/**
 *  The newest items, replacing whatever the client had. `seq` is the
 *  timeline's version after them.
 */
{ type: "reset"; 
/**  The timeline's version after these items. */
seq: Seq; 
/**  Oldest first. */
items: TimelineItem[]; 
/**  Whether there are items before the first of these. */
has_older: boolean } | 
/**  Changes in order. `seq` is the version after the last one. */
{ type: "events"; 
/**  The timeline's version after the last event. */
seq: Seq; 
/**  Applied in order. One this build can't read is left out. */
events: TimelineEvent[] } | 
/**  Items before the oldest the client has, oldest first. */
{ type: "older"; 
/**  Oldest first. */
items: TimelineItem[]; 
/**  Whether there are items before the first of these. */
has_older: boolean };

/**
 *  A point in time, as milliseconds since the Unix epoch in UTC.
 * 
 *  TypeScript sees a plain `number`. JavaScript numbers hold every integer up
 *  to 2^53 exactly, and 2^53 milliseconds is about 285,000 years.
 */
export type Timestamp = number;

/**  One entry in an agent's to-do list. */
export type Todo = {
	/**  What to do. */
	text: string,
	/**  How far along it is. */
	state: TodoState,
};

/**  How far along a to-do is. */
export type TodoState = 
/**  Not started. */
"pending" | 
/**  Being worked on. */
"in_progress" | 
/**  Finished. */
"done";

/**  How a badge or a header reads. */
export type Tone = 
/**  Plain. */
"neutral" | 
/**  Worth a look. */
"info" | 
/**  Went well. */
"good" | 
/**  Needs care. */
"warn" | 
/**  Went wrong. */
"bad";

/**  An agent CLI that MaxHQ can update. */
export type Tool = 
/**  Claude Code. */
"claude" | 
/**  The Codex CLI. */
"codex" | 
/**  The Cursor CLI. */
"cursor";

/**  What a tool call came to, as the caller reads it. */
export type ToolAnswer = {
	/**  The text, often JSON. */
	text: string,
	/**  Whether the call failed or was refused. */
	failed: boolean,
	/**  Images that go with the text, such as a lease's screenshot. */
	images?: ToolImage[],
};

/**
 *  One call to an agent tool, by the tool's own name, such as
 *  `start_agent`, with its arguments as the tool's schema gives them.
 */
export type ToolCall = {
	/**  The tool. */
	tool: string,
	/**  Its arguments. */
	arguments: unknown,
};

/**  One image in a tool's answer. */
export type ToolImage = {
	/**  Its type, such as `image/png`. */
	mime: string,
	/**  Its bytes, in base64. */
	data: string,
};

/**  One tool in one place. */
export type ToolInfo = {
	/**  Which tool. */
	kind: ToolKind,
	/**  Where it's installed. */
	place: ToolPlace,
	/**  The binary's path, when found. */
	path: string | null,
	/**  The installed version, when it answered. */
	version: string | null,
	/**  The newest release, when known. */
	latest: string | null,
	/**  Who installed it. */
	owner: ToolOwner,
	/**  How it was installed, such as `native` or `npm`. */
	method: string,
	/**  Whether MaxHQ updates it. */
	update: ToolUpdate,
	/**  What it's doing now. */
	state: ToolState,
};

/**  Which tool a [`ToolInfo`] is. */
export type ToolKind = 
/**  An agent CLI. */
{ type: "agent"; 
/**  Which one. */
tool: Tool } | 
/**  A tool MaxHQ installs for the agents and itself. */
{ type: "helper"; 
/**  Which one. */
tool: HelperTool } | 
/**  An agent from the ACP registry. */
{ type: "acp"; 
/**  Its id in the registry. */
id: string };

/**  Who installed a CLI. */
export type ToolOwner = 
/**  MaxHQ, in a workspace it made. */
"max_hq" | 
/**  You. */
"user";

/**  Where an install is. */
export type ToolPhase = 
/**  Working out what to fetch. */
"resolving" | 
/**  Downloading. */
"downloading" | 
/**  Checking the download's SHA-256. */
"verifying" | 
/**  Unpacking or installing into a staging folder. */
"installing" | 
/**  Publishing the staged install and its links. */
"linking";

/**  Where a CLI is installed. */
export type ToolPlace = 
/**  On the device itself. */
{ type: "host" } | 
/**  In a container workspace. */
{ type: "workspace"; 
/**  The workspace. */
workspace: WorkspaceId };

/**  What a tool's install or update is doing. */
export type ToolState = 
/**  Nothing. */
{ type: "idle" } | 
/**  Installing or updating. */
{ type: "running"; 
/**  The latest progress line. */
message: string; 
/**
 *  Where an install is, when the installer runs it. An update from
 *  before installs leaves this out.
 */
phase?: ToolPhase | null; 
/**  Bytes downloaded so far, while downloading. */
bytes_done?: number | null; 
/**  Bytes to download in all, when known. */
bytes_total?: number | null } | 
/**
 *  The install waits for you to accept licences, with
 *  [`crate::message::ClientMessage::AcceptLicence`].
 */
{ type: "licences"; 
/**  The licences not yet accepted. */
pending: PendingLicence[] } | 
/**  The last update failed. */
{ type: "failed"; 
/**  Why. */
reason: string };

/**  One CLI in one place, for [`ClientMessage::UpdateTools`]. */
export type ToolTarget = {
	/**  Which CLI. */
	tool: Tool,
	/**  Where it's installed. */
	place: ToolPlace,
};

/**  Whether MaxHQ updates a CLI. */
export type ToolUpdate = 
/**  MaxHQ installed it, so it updates it. */
{ type: "auto" } | 
/**  You ticked it for MaxHQ to update. */
{ type: "allowed" } | 
/**  MaxHQ could update it once you tick it. */
{ type: "needs_tick" } | 
/**  MaxHQ can't update it. Run the command yourself. */
{ type: "manual"; 
/**  What to run. */
command: string } | 
/**
 *  MaxHQ never updates it, as with Cursor: it has no package to
 *  check, so you or the CLI itself keep it current.
 */
{ type: "never" };

/**  One upload or download of files between a client and a device. */
export type TransferId = string;

/**  How far one transfer has got, as its report hears it. */
export type TransferProgress = {
	/**  The transfer, which a `cancel_transfer` request takes. */
	transfer: TransferId,
	/**  Bytes on their way so far, across every file in it. */
	sent: number,
	/**  Bytes in the whole transfer, or 0 before it's known. */
	total: number,
	/**  The file on its way now, as a path inside the transfer. */
	file: string,
	/**  What the transfer is doing. */
	state: TransferState,
};

/**  What a transfer is doing. */
export type TransferState = 
/**  Bytes are moving. */
"uploading" | 
/**  The far end has no room yet, so bytes wait for it. */
"waiting" | 
/**  The link dropped. It picks up again once the link is back. */
"paused" | 
/**  Every byte arrived. */
"done" | 
/**  It stopped for good. */
"failed";

/**
 *  A skill folder's content hash: hex SHA-256 over its sorted files, each
 *  with its path, executable bit and hash. The same files always give the
 *  same hash.
 */
export type TreeHash = string;

/**  What makes a task run. */
export type Trigger = 
/**  Every so many minutes. */
({ type: "every"; 
/**  At least 1. */
minutes: number }) & { days?: never; events?: never; repo?: never; rules?: never; time?: never; zone?: never } | 
/**  At a time of day, on some days of the week. */
({ type: "at"; 
/**  The time, in `zone`. */
time: TimeOfDay; 
/**  The days. None means every day. */
days: Days; 
/**  The time zone the time is in. */
zone: Zone }) & { events?: never; minutes?: never; repo?: never; rules?: never } | 
/**  On each request to the task's webhook. */
{
	type: "hook",
} & Hook | 
/**  On events in a GitHub repository, which `maxd` polls for. */
({ type: "github_events"; 
/**  The repository, as "owner/name". */
repo: string; 
/**
 *  The event types, such as `issues` or `pull_request`, as GitHub's
 *  webhooks name them. `maxd` maps each polled event to these.
 */
events: string[]; 
/**  Which events run the task, the same way a webhook's do. */
rules: HookRules }) & { days?: never; minutes?: never; time?: never; zone?: never };

/**  How a tunnel stream ends. */
export type TunnelEnd = 
/**  The sender is done writing, and still reads. */
"write" | 
/**  The connection is aborted both ways. */
"reset";

/**  One turn, as the CLI numbers it. */
export type TurnId = string;

/**  A container workspace's unsaved work, summed over its checkouts. */
export type UnsavedSummary = {
	/**  Files changed and not committed. */
	changed: number,
	/**  Commits not on any remote. */
	commits: number,
	/**  Checkouts whose branch has no upstream. */
	no_upstream: number,
	/**  When the guest read it. */
	read_at: Timestamp,
};

/**  Which binary [`ClientMessage::InstallUpdate`] installs. */
export type UpdateKind = 
/**  `maxd` itself. */
"maxd" | 
/**  The binary each container workspace runs as `maxd guest`. */
"guest";

/**
 *  Your settings for the app's updates, kept with this Mac's other app
 *  settings.
 */
export type UpdatePrefs = {
	/**
	 *  Whether the app looks for an update when it starts and every few
	 *  hours after.
	 */
	auto_check?: boolean,
};

/**  Where the app's own update stands. */
export type UpdateStatus = 
/**  This copy doesn't offer updates, for `reason`. */
{ state: "unavailable"; 
/**  Why not. */
reason: NoUpdates } | 
/**  It hasn't looked yet. */
{ state: "idle" } | 
/**  It's looking now. */
{ state: "checking" } | 
/**  It looked, and this is the newest version. */
{ state: "up_to_date"; 
/**  When it looked. */
checked_at: Timestamp } | 
/**  A newer version is out. */
{ state: "available"; 
/**  The newer version, such as `0.2.0`. */
version: string } | 
/**  The newer version is on its way. */
{ state: "downloading"; 
/**  The version. */
version: string; 
/**  Bytes so far. */
downloaded: number; 
/**  All of it, when the server says. */
total: number | null } | 
/**  It's downloaded and going into place. The app restarts next. */
{ state: "installing"; 
/**  The version. */
version: string } | 
/**  Looking or installing failed. */
{ state: "failed"; 
/**  Why, as the updater said. */
reason: string; 
/**
 *  The newer version, when it failed installing one, so you can
 *  try again.
 */
version: string | null };

/**  Where uploaded files come from. */
export type UploadSource = 
/**  Bytes the client sends in transfer frames, one entry per file. */
{ type: "stream"; 
/**  The name the upload shows as, such as the folder's. */
name: string; 
/**  Every file, folder and link, folders before what's in them. */
entries: ManifestEntry[] } | 
/**  A path on the device itself, as [`AttachmentSource::Path`] is. */
{ type: "device_path"; 
/**  Absolute path on the device. */
path: string };

/**  Where uploaded files go. */
export type UploadTarget = 
/**  The device's staging folder, for a new agent or one in a folder. */
{ type: "device" } | 
/**  A workspace's container, for an agent not started yet. */
{ type: "workspace"; 
/**  The workspace. */
workspace: WorkspaceId } | 
/**  A running agent's attachments folder. */
{ type: "agent"; 
/**  The agent. */
agent: AgentId } | 
/**
 *  The device's skill store, as one skill folder. `maxd` checks its
 *  hash before it lands.
 */
{ type: "skill_store"; 
/**  The folder's hash. */
tree: TreeHash };

/**  An account's rate limits as the vendor last reported them. */
export type Usage = {
	/**
	 *  When the vendor reported these numbers, which can be earlier than
	 *  when `maxd` read them from a cache.
	 */
	checked_at: Timestamp,
	/**  Where the numbers came from. */
	source: UsageSource,
	/**  Every limit, the account's own first, shortest window first. */
	windows: UsageWindow[],
};

/**  A usage check that didn't work. */
export type UsageFailure = {
	/**  When the check ran. */
	at: Timestamp,
	/**  What went wrong, such as "logged out" or "claude not found". */
	reason: string,
};

/**  How a usage window moves. */
export type UsagePeriod = 
/**  It covers the last `window_minutes`, as Claude's and Codex's do. */
"rolling" | 
/**  It covers the plan's billing cycle and resets when the cycle ends. */
"billing_cycle";

/**  Where a usage reading came from. */
export type UsageSource = 
/**  The figures Claude Code keeps in `.claude.json` after its own check. */
"claude_cache" | 
/**  A `get_usage` control request to a short-lived `claude` process. */
"claude_probe" | 
/**  `account/rateLimits/read` from `codex app-server`. */
"codex_app_server" | 
/**  The rate limits a Codex session wrote to its rollout file. */
"codex_rollout" | 
/**  Cursor's dashboard, asked for the current billing cycle. */
"cursor_dashboard";

/**  Money spent against a limit, in US cents. */
export type UsageSpend = {
	/**  What's been spent. */
	used_cents: number,
	/**  The most it may spend. */
	limit_cents: number,
};

/**
 *  One usage limit, such as a 5-hour or a weekly window, or a month of a
 *  plan's billing cycle.
 */
export type UsageWindow = {
	/**
	 *  Unset for the account's own limits. Set for a limit that covers part
	 *  of it, such as one model's weekly limit or a Codex limit other than
	 *  `codex`. A billing cycle's parts are `auto`, `api` and `on_demand`.
	 */
	scope: string | null,
	/**
	 *  The window's length. 300 is the 5-hour window and 10080 the weekly
	 *  one. A billing cycle has no fixed length and sends 0.
	 */
	window_minutes: number,
	/**
	 *  Whether the window rolls or follows the billing cycle. A `maxd` from
	 *  before billing cycles leaves this out.
	 */
	period?: UsagePeriod,
	/**  How much of the limit is used, from 0 to 100. */
	used_percent: number | null,
	/**  When the window resets, if the vendor said. */
	resets_at: Timestamp | null,
	/**
	 *  What a limit set in money has spent, such as Cursor's on-demand
	 *  spend. `used_percent` is the same figure as a share of the limit.
	 */
	spend?: UsageSpend | null,
};

/**  What `maxd` and everything it started used over one stretch of time. */
export type UseBucket = {
	/**  When the stretch starts. */
	started_at: Timestamp,
	/**  When it ends. */
	ended_at: Timestamp,
	/**  The average CPU over the samples in it, in percent of one CPU. */
	avg_cpu: number,
	/**  The highest CPU in one sample. */
	max_cpu: number,
	/**  The most memory in one sample, in bytes. */
	max_rss: number,
	/**  The most processes in one sample. */
	max_processes: number,
};

/**  A message you send to an agent. */
export type UserInput = {
	/**  What you typed, with U+FFFC where each placed ref sits. */
	text: string,
	/**  Attachments staged with [`ClientMessage::StageAttachment`], in order. */
	attachments: AttachmentId[],
	/**
	 *  The context in the text, in text order. An attachment without a ref
	 *  is listed after the text. A client from before sends none.
	 */
	refs?: InlineRef[],
};

/**  The company behind an agent CLI. */
export type Vendor = 
/**  Anthropic's Claude Code. */
"claude" | 
/**  OpenAI's Codex CLI. */
"codex" | 
/**  Cursor's CLI, driven over the Agent Client Protocol. */
"cursor" | 
/**
 *  Any other agent that speaks the Agent Client Protocol, run as a
 *  local command. Its account says which one.
 */
"acp";

/**
 *  A note version's hash: lowercase hex SHA-256 over a canonical JSON of
 *  its note, sorted parents, title, body and whether it's deleted. When
 *  and by whom stay out, so two devices that make the same merge make the
 *  same version.
 */
export type VersionHash = string;

/**  Sent with the view's changes, oldest first, at most once a frame. */
export type ViewChanged = Delta[];

/**  The VM behind a [`TestHostBackend::MacVm`] host. */
export type VmSize = {
	/**  The base disk on the Mac, in bytes. */
	disk_bytes: number,
	/**  The memory it runs with, in bytes. */
	memory_bytes: number,
};

/**  How a turn ended, for a wake. */
export type WakeTurn = 
/**  It finished. */
"finished" | 
/**  It waits for input. */
"needs_input" | 
/**  It stopped. */
"stopped";

/**  What a web item did. */
export type WebAction = 
/**  Searched the web. */
"search" | 
/**  Fetched one page. */
"fetch";

/**
 *  A point in the webview, in CSS pixels from its top left corner, such as
 *  a `contextmenu` event's `clientX` and `clientY`.
 */
export type WebviewPoint = {
	/**  Pixels from the left edge. */
	x: number,
	/**  Pixels from the top edge. */
	y: number,
};

/**  A day of the week. */
export type Weekday = 
/**  Monday. */
"monday" | 
/**  Tuesday. */
"tuesday" | 
/**  Wednesday. */
"wednesday" | 
/**  Thursday. */
"thursday" | 
/**  Friday. */
"friday" | 
/**  Saturday. */
"saturday" | 
/**  Sunday. */
"sunday";

/**  One workflow update, as a window's channel carries it. */
export type WorkflowMessage = {
	/**  The run that changed. */
	run: RunKey,
	/**  What changed. */
	update: WorkflowUpdate,
};

/**  One run, as the view lists it. */
export type WorkflowRun = {
	/**  The run's id, from [`RunKey::id`]. */
	id: WorkflowRunId,
	/**  The run. */
	key: RunKey,
	/**  What it's called. */
	label: string,
	/**  How far it is. */
	progress: Progress,
	/**  The nodes busy now. */
	current: string[],
	/**  Whether a node, or the run's lead, waits for you. */
	needs_you: boolean,
	/**  The agents that lead it. */
	orchestrators: AgentId[],
	/**  When anything last happened. */
	last_activity: Timestamp | null,
	/**  Whether it finished. */
	done: boolean,
	/**
	 *  Whether it finished by failing. Sent since
	 *  [`WORKFLOW_RUN_AGENTS_SINCE`](crate::message::WORKFLOW_RUN_AGENTS_SINCE).
	 */
	failed?: boolean,
	/**
	 *  The agents bound to its nodes, other than its leads. Sent since
	 *  [`WORKFLOW_RUN_AGENTS_SINCE`](crate::message::WORKFLOW_RUN_AGENTS_SINCE).
	 */
	agents?: AgentId[],
};

/**  One run of a workflow, derived from its key. */
export type WorkflowRunId = string;

/**  What a client gets about an open run. */
export type WorkflowUpdate = 
/**  The whole run, to replace what the client has. */
{ kind: "reset"; run: RunSnapshot } | 
/**  A change to what it has. */
{ kind: "patch"; run: RunPatch };

/**  A checkout of a project on one device. */
export type Workspace = {
	/**  Stable for the life of the checkout. */
	id: WorkspaceId,
	/**  The project this is a checkout of. Unset until you assign one. */
	project: ProjectId | null,
	/**  The device that holds the checkout. */
	device: DeviceId,
	/**  Where the checkout lives on that device. */
	location: WorkspaceLocation,
	/**  Set only for workspaces MaxHQ made and runs. */
	managed?: ManagedWorkspace | null,
	/**
	 *  How a clone into this folder is going, for a folder MaxHQ clones.
	 *  None once the clone is done. A `maxd` from before it leaves this
	 *  out.
	 */
	clone?: CloneProgress | null,
};

/**  The networks and storage pools a device's Incus offers. */
export type WorkspaceHost = {
	/**  Network names, such as "agentbr0". */
	networks: string[],
	/**  Storage pool names, such as "agents". */
	pools: string[],
};

/**  A checkout of a project on a device, either a folder or a container. */
export type WorkspaceId = string;

/**  Where a workspace lives. */
export type WorkspaceLocation = 
/**  A folder on the device itself. */
{ type: "folder"; 
/**  Absolute path on the device. */
path: string } | 
/**  A folder inside a container on the device. */
{ type: "container"; 
/**  The Incus instance name. */
instance: string; 
/**  Absolute path inside the container. */
path: string };

/**  One snapshot of a container workspace. */
export type WorkspaceSnapshot = {
	/**
	 *  Its name in Incus, such as `auto-2026-11-02-1400` or
	 *  `mhq-before-rollback`.
	 */
	name: string,
	/**  When it was taken. */
	taken_at: Timestamp,
	/**  When Incus deletes it, or none for one that's kept. */
	expires_at: Timestamp | null,
};

/**  What a new container workspace should be. */
export type WorkspaceSpec = {
	/**  The project to check out in it. */
	project: ProjectId,
	/**  The device whose Incus runs it. */
	device: DeviceId,
	/**  The container's name after `mhq-`. The project's name when unset. */
	name: string | null,
	/**  Whether it starts when its device does, per A-11. */
	start_at_boot: boolean,
};

/**  What a container workspace is doing. */
export type WorkspaceState = 
/**  Being made, one step at a time. */
{ state: "creating"; 
/**  The step running now, for a person to read. */
step: string; 
/**  Steps finished so far. */
done: number; 
/**  Steps in all. */
of: number } | 
/**  Starting up. */
{ state: "starting" } | 
/**  Running, so agents can start in it. */
{ state: "running" } | 
/**  Shutting down. */
{ state: "stopping" } | 
/**  Stopped, with its files kept. */
{ state: "stopped" } | 
/**  Being deleted. */
{ state: "deleting" } | 
/**  A-11. The container's storage pool isn't available. Shown purple. */
{ state: "storage_locked" } | 
/**  Something went wrong that needs you. */
{ state: "failed"; 
/**  What went wrong, for a person to read. */
reason: string };

/**
 *  An IANA time zone name, such as `Europe/Amsterdam`. The app takes it
 *  from the Mac when you make the task, so a task on a device set to UTC
 *  still runs at the time you typed.
 */
export type Zone = string;
